window.ANSWER_TERMS = {"ATP":{"match":"adenosinetrifosfaat|adenosine trifosfaat|adenosine-trifosfaat|ATP","title":"ATP (adenosinetrifosfaat)","short":"ATP is de energiemunt van de cel: bij afsplitsing van de derde fosfaatgroep komt energie vrij die transport, contractie en biosynthese aandrijft.","definition":"<p><strong>ATP</strong> (adenosinetrifosfaat) bestaat uit adenine, ribose en drie fosfaatgroepen. Hydrolyse van de eindstandige fosfaatbinding (ATP → ADP + P<sub>i</sub>) levert ongeveer 30 kJ/mol — genoeg om ongunstige reacties te koppelen aan een gunstige: spiercontractie, de Na⁺/K⁺-ATPase, en de opbouw van eiwitten, vetten en DNA.</p><p>Het meeste ATP komt uit de <em>oxidatieve fosforylering</em> in het mitochondrion: de elektronentransportketen pompt protonen naar de intermembraanruimte, en ATP-synthase laat die protonengradiënt terugstromen en maakt daarmee ATP (chemiosmose). Glycolyse en de citroenzuurcyclus leveren daarnaast rechtstreeks een kleine hoeveelheid.</p><p>De cel slaat ATP nauwelijks op — de voorraad gaat in seconden — dus productie en verbruik zijn strak gekoppeld: veel ADP versnelt de verbranding, overmaat ATP remt die af.</p>","image_url":"","wiki_titles":["Adenosine triphosphate","ATP synthase"]},"ruw endoplasmatisch reticulum":{"title":"Ruw endoplasmatisch reticulum","short":"Deel van het ER bezet met ribosomen; hier worden eiwitten voor secretie en membranen gemaakt.","definition":"<p>Het <b>ruw endoplasmatisch reticulum</b> dankt zijn 'ruwe' aanzien aan de ribosomen op het oppervlak. Deze ribosomen synthetiseren eiwitten die het ER in worden geloodst.</p><p>In het ER-lumen worden die eiwitten gevouwen en van suikergroepen voorzien, op weg naar het Golgi-complex, de membranen of secretie.</p>","image_url":"","wiki_title":"Endoplasmic reticulum","match":"ruw endoplasmatisch reticulum|ruw ER"},"mitochondrion":{"title":"Mitochondrion","short":"De 'energiecentrale' van de cel; produceert ATP via de citroenzuurcyclus en oxidatieve fosforylering.","definition":"<p>Het <b>mitochondrion</b> heeft een dubbele membraan; de binnenste is sterk geplooid (cristae). Hier vinden de citroenzuurcyclus en de elektronentransportketen plaats.</p><p>Zo levert het mitochondrion het grootste deel van de ATP van de cel. Het bevat eigen DNA en kan zich delen.</p>","image_url":"","wiki_title":"Mitochondrion","match":"mitochondrion|mitochondriën|mitochondrien|mitochondria|mitochondrium"},"actine":{"title":"Actine","short":"Eiwit dat microfilamenten vormt; betrokken bij celvorm, celbeweging en spiercontractie.","definition":"<p><b>Actine</b> is een van de meest voorkomende eiwitten in de cel. Losse moleculen (G-actine) polymeriseren tot dunne draden (F-actine): de microfilamenten van het cytoskelet.</p><p>Actinefilamenten geven de cel vorm, maken beweging en deling mogelijk en vormen samen met myosine het contractiele apparaat van spiercellen.</p>","image_url":"","wiki_title":"Actin","match":"actine|actinefilamenten|actinefilament"},"myosine":{"title":"Myosine","short":"Motoreiwit dat langs actinefilamenten beweegt en zo spiercontractie en intracellulair transport aandrijft.","definition":"<p><b>Myosine</b> is een motoreiwit dat onder verbruik van ATP kracht levert door langs actinefilamenten te 'lopen'.</p><p>In spiercellen glijden myosine- en actinefilamenten langs elkaar, wat de spier doet samentrekken (het glijdende-filamentmodel).</p>","image_url":"","wiki_title":"Myosin","match":"myosine|myosinefilamenten|myosinefilament"},"autocriene signalering":{"title":"Autocriene signalering","short":"De cel scheidt een signaalstof af waarop hij zélf reageert.","definition":"<p>Bij <b>autocriene signalering</b> geeft een cel een signaalmolecuul af dat bindt aan receptoren op diezelfde cel.</p><p>De cel stuurt dus zichzelf. Dit komt onder meer voor bij groeiregulatie en bij tumorcellen die hun eigen groei aanjagen.</p>","image_url":"","wiki_title":"Autocrine signaling","match":"autocriene signalering|autocrien|autocriene secretie|autocriene celsignalering"},"paracriene signalering":{"title":"Paracriene signalering","short":"Een cel scheidt een signaalstof af die alleen op nabijgelegen cellen inwerkt.","definition":"<p>Bij <b>paracriene signalering</b> werkt het afgegeven signaalmolecuul lokaal in op cellen in de directe omgeving.</p><p>De stof wordt snel afgebroken of opgenomen, zodat het effect beperkt blijft tot de buurt. Voorbeeld: histamine bij ontsteking.</p>","image_url":"","wiki_title":"Paracrine signaling","match":"paracriene signalering|paracrien|paracriene secretie|paracriene celsignalering"},"endocriene signalering":{"title":"Endocriene signalering","short":"Klieren geven hormonen af aan het bloed, dat ze naar verre doelorganen vervoert.","definition":"<p>Bij <b>endocriene signalering</b> scheiden endocriene klieren hormonen rechtstreeks in de bloedbaan uit.</p><p>Via het bloed bereiken de hormonen doelcellen elders in het lichaam die de bijbehorende receptor dragen. Het effect is trager maar wijdverbreid.</p>","image_url":"","wiki_title":"Endocrine system","match":"endocriene signalering|endocrien|endocriene secretie|endocriene celsignalering"},"glycoproteine":{"title":"Glycoproteïne","short":"Eiwit met aangehechte suikerketens; veel membraan- en secretie-eiwitten zijn geglycosyleerd.","definition":"<p>Een <b>glycoproteïne</b> is een eiwit waaraan tijdens de rijping in ER en Golgi suikerketens zijn gekoppeld (glycosylering).</p><p>Ze zitten veel in de celmembraan en in secreten en spelen een rol bij herkenning, adhesie en bescherming.</p>","image_url":"","wiki_title":"Glycoprotein","match":"glycoproteïne|glycoproteine|glycoproteïnen|glycoproteinen|glycoproteinen"},"cholesterol":{"title":"Cholesterol","short":"Vetachtige stof die de celmembraan stevigheid en de juiste vloeibaarheid geeft en grondstof is voor steroïden.","definition":"<p><b>Cholesterol</b> is een steroïd dat tussen de fosfolipiden van de celmembraan zit en de membraanvloeibaarheid stabiliseert.</p><p>Het is bovendien de grondstof voor steroïdhormonen, vitamine D en galzouten.</p>","image_url":"","wiki_title":"Cholesterol","match":"cholesterol"},"autofagie":{"title":"Autofagie","short":"Proces waarbij de cel eigen versleten onderdelen insluit en met lysosomen afbreekt en recyclet.","definition":"<p><b>Autofagie</b> ('zelf-eten') is het proces waarbij de cel eigen organellen of eiwitaggregaten omsluit in een autofagosoom.</p><p>Dat fuseert met een lysosoom, waarna de inhoud wordt afgebroken en hergebruikt — belangrijk bij hongertoestand en kwaliteitsbewaking.</p>","image_url":"","wiki_title":"Autophagy","match":"autofagie"},"apoptose":{"title":"Apoptose","short":"Geprogrammeerde celdood: een geordend 'zelfmoordprogramma' dat de cel netjes opruimt zonder ontsteking.","definition":"<p><b>Apoptose</b> is gecontroleerde celdood. De cel krimpt, het DNA wordt in stukken geknipt en de cel valt uiteen in nette blaasjes (apoptotic bodies).</p><p>Macrofagen ruimen die op zonder ontstekingsreactie. Het is essentieel voor ontwikkeling en het verwijderen van beschadigde cellen.</p>","image_url":"","wiki_title":"Apoptosis","match":"apoptose"},"glycolyse":{"title":"Glycolyse","short":"Afbraak van glucose tot pyruvaat in het cytoplasma, met een kleine netto-opbrengst aan ATP en NADH.","definition":"<p><b>Glycolyse</b> splitst in het cytoplasma één glucose in tien stappen tot twee moleculen pyruvaat.</p><p>Het levert netto 2 ATP en 2 NADH op en verloopt zonder zuurstof. Bij aanwezigheid van zuurstof gaat pyruvaat de citroenzuurcyclus in.</p>","image_url":"","wiki_title":"Glycolysis","match":"glycolyse"},"citroenzuurcyclus":{"title":"Citroenzuurcyclus","short":"Kringloop in het mitochondrion die acetyl-CoA volledig oxideert en NADH, FADH₂ en CO₂ oplevert.","definition":"<p>De <b>citroenzuurcyclus</b> (Krebscyclus) vindt plaats in de mitochondriale matrix. Acetyl-CoA gaat de cyclus in en wordt stapsgewijs geoxideerd.</p><p>Er ontstaan NADH en FADH₂ (die de elektronentransportketen voeden), wat GTP/ATP en CO₂ als afvalstof.</p>","image_url":"","wiki_title":"Citric acid cycle","match":"citroenzuurcyclus|krebscyclus"},"oxidatieve fosforylering":{"title":"Oxidatieve fosforylering","short":"Vorming van het grootste deel van de ATP via de elektronentransportketen en ATP-synthase in het mitochondrion.","definition":"<p>Bij <b>oxidatieve fosforylering</b> drijft de protongradiënt van de elektronentransportketen het enzym ATP-synthase aan.</p><p>Zo wordt uit ADP en fosfaat ATP gevormd — de belangrijkste ATP-bron van de cel, waarvoor zuurstof nodig is.</p>","image_url":"","wiki_title":"Oxidative phosphorylation","match":"oxidatieve fosforylering"},"acetyl-coa":{"title":"Acetyl-CoA","short":"Centrale metaboliet die een acetylgroep de citroenzuurcyclus in brengt; knooppunt van suiker-, vet- en eiwitafbraak.","definition":"<p><b>Acetyl-CoA</b> ontstaat uit pyruvaat (uit glycolyse), vetzuren en sommige aminozuren.</p><p>Het draagt zijn acetylgroep de citroenzuurcyclus in en is zo het centrale knooppunt van het energiemetabolisme.</p>","image_url":"","wiki_title":"Acetyl-CoA","match":"acetyl-coa|acetyl coa"},"pyruvaat":{"title":"Pyruvaat","short":"Eindproduct van de glycolyse; gaat bij zuurstof over in acetyl-CoA, zonder zuurstof in lactaat.","definition":"<p><b>Pyruvaat</b> (pyrodruivenzuur) is het eindproduct van de glycolyse.</p><p>Met zuurstof wordt het in het mitochondrion omgezet tot acetyl-CoA voor de citroenzuurcyclus; zonder zuurstof wordt het via gisting lactaat.</p>","image_url":"","wiki_title":"Pyruvic acid","match":"pyruvaat|pyrodruivenzuur"},"citraat":{"title":"Citraat","short":"Eerste product van de citroenzuurcyclus, gevormd uit acetyl-CoA en oxaalacetaat.","definition":"<p><b>Citraat</b> (citroenzuur) ontstaat wanneer acetyl-CoA in de citroenzuurcyclus aan oxaalacetaat wordt gekoppeld.</p><p>Het is de eerste stap van de cyclus; de naamgever citroenzuurcyclus verwijst ernaar.</p>","image_url":"","wiki_title":"Citric acid","match":"citraat"},"fosforylering":{"title":"Fosforylering","short":"Toevoeging van een fosfaatgroep aan een eiwit; een veelgebruikte aan/uit-schakelaar van eiwitactiviteit.","definition":"<p><b>Fosforylering</b> is het koppelen van een fosfaatgroep aan een eiwit door een kinase. Een fosfatase haalt hem er weer af.</p><p>Zo schakelen cellen eiwitten razendsnel aan of uit — de basis van veel signaaltransductie.</p>","image_url":"","wiki_title":"Phosphorylation","match":"fosforylering|fosforylatie"},"macrofaag":{"title":"Macrofaag","short":"Grote fagocyt in de weefsels die pathogenen en celresten opruimt en antigenen presenteert.","definition":"<p>De <b>macrofaag</b> ontstaat uit een monocyt die het weefsel is binnengegaan. Hij fagocyteert bacteriën, dode cellen en afval.</p><p>Als antigeenpresenterende cel activeert hij ook T-cellen en scheidt hij ontstekingsmediatoren uit. In de huid heten verwante cellen histiocyten.</p>","image_url":"","wiki_title":"Macrophage","match":"macrofaag|macrofagen"},"lymfocyt":{"title":"Lymfocyt","short":"Witte bloedcel van de specifieke afweer; omvat de B-cellen (antistoffen) en T-cellen.","definition":"<p>De <b>lymfocyt</b> is de sleutelcel van het adaptieve (specifieke) immuunsysteem. B-lymfocyten maken antistoffen; T-lymfocyten doden geïnfecteerde cellen of sturen de afweer aan.</p><p>Lymfocyten circuleren tussen bloed, lymfe en lymfoïde organen.</p>","image_url":"","wiki_title":"Lymphocyte","match":"lymfocyt|lymfocyten"},"milt":{"title":"Milt","short":"Lymfoïd orgaan dat oude bloedcellen afbreekt en bloedgedragen ziekteverwekkers filtert.","definition":"<p>De <b>milt</b> filtert het bloed: de rode pulpa ruimt versleten erytrocyten op, de witte pulpa herbergt lymfocyten voor de afweer tegen bloedgedragen pathogenen.</p><p>Ook dient de milt als bloedreservoir.</p>","image_url":"","wiki_title":"Spleen","match":"milt"},"beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"beenmerg|het beenmerg"},"collageen":{"title":"Collageen","short":"Sterkste structuureiwit van het lichaam; hoofdbestanddeel van bindweefsel, dermis, pezen en bot.","definition":"<p><b>Collageen</b> is het meest voorkomende eiwit in het lichaam en vormt sterke, drievoudig gewonden vezels.</p><p>In de dermis geeft het de huid trekvastheid; fibroblasten maken het aan. Voor de aanmaak is vitamine C nodig (hydroxylering van proline).</p>","image_url":"","wiki_title":"Collagen","match":"collageen"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"vesikel":{"title":"Vesikel","short":"Klein, met helder vocht gevuld blaasje in de huid (< ~1 cm).","definition":"<p>Een <b>vesikel</b> (vesicula) is een klein blaasje gevuld met helder vocht, kleiner dan ongeveer 1 cm.</p><p>Vesikels komen voor bij o.a. herpes, waterpokken en acuut eczeem. Een groter blaasje heet een bulla.</p>","image_url":"","wiki_title":"Blister","match":"vesikel|vesikels|vesicula|vesiculae"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"radiotherapie":{"title":"Radiotherapie","short":"Behandeling met ioniserende straling die het DNA van tumorcellen beschadigt.","definition":"<p><b>Radiotherapie</b> (bestraling) gebruikt ioniserende straling om het DNA van kankercellen zodanig te beschadigen dat ze afsterven.</p><p>In de dermatologie is het een alternatief voor chirurgie bij bijvoorbeeld basaal- en plaveiselcelcarcinomen, vooral bij oudere patiënten of moeilijke locaties.</p>","image_url":"","wiki_title":"Radiation therapy","match":"radiotherapie"},"autosomaal dominant":{"title":"Autosomaal dominant","short":"Overervingspatroon waarbij één afwijkend gen (op een niet-geslachtschromosoom) al ziekte geeft.","definition":"<p>Bij <b>autosomaal dominante</b> overerving volstaat één gemuteerd allel op een autosoom om de aandoening tot uiting te laten komen.</p><p>Aangedane ouders geven het gemiddeld aan de helft van hun kinderen door; de aandoening komt in elke generatie voor, ongeacht geslacht.</p>","image_url":"","wiki_title":"Dominance (genetics)","match":"autosomaal dominant"},"somatostatine analoog":{"title":"Somatostatine-analoog","short":"Somatostatine-analogen (zoals octreotide) bootsen somatostatine na en remmen de afgifte van groeihormoon en veel maag-darmhormonen.","definition":"<p><strong>Somatostatine-analogen</strong> zoals <em>octreotide</em> en <em>lanreotide</em> zijn langwerkende varianten van het hormoon somatostatine. Ze binden aan somatostatinereceptoren en remmen de afgifte van o.a. groeihormoon, TSH, insuline, glucagon en gastro-intestinale hormonen.</p><p>Ze worden gebruikt bij acromegalie, hormoonproducerende neuro-endocriene tumoren (bijv. carcinoïdsyndroom) en bij varicesbloedingen (vermindering van de splanchnische doorbloeding).</p>","image_url":"","wiki_title":"Octreotide","match":"somatostatine analoog|somatostatine-analoog|somatostatineanaloog|octreotide|lanreotide","option_only":true},"volle agonist":{"title":"Volle agonist","short":"Een volle agonist bindt aan een receptor en activeert die maximaal: de intrinsieke activiteit (efficacy) is 1.","definition":"<p>Een <strong>volle agonist</strong> bindt aan een receptor en brengt het maximaal mogelijke effect teweeg; de <em>intrinsieke activiteit</em> (efficacy) is 1.</p><p>Affiniteit (hoe goed een stof bindt) en efficacy (hoe sterk de stof de receptor activeert na binding) zijn verschillende eigenschappen.</p>","image_url":"","wiki_title":"","match":"volle agonist|volledige agonist|full agonist","option_only":true},"alfa 1 receptor":{"title":"α1-adrenerge receptor","short":"De α1-receptor is een adrenerge receptor (Gq) op gladde spier; activatie geeft vasoconstrictie, mydriasis en contractie van de blaassfincter.","definition":"<p>De <strong>α1-adrenerge receptor</strong> is een G-eiwitgekoppelde receptor (Gq) die via fosfolipase C, IP<sub>3</sub> en calcium gladde spiercellen laat samentrekken.</p><p>Effecten van activatie (door noradrenaline/adrenaline): <em>vasoconstrictie</em> (bloeddrukstijging), mydriasis via de m. dilatator pupillae en contractie van de interne blaas- en prostaatsfincter. α1-blokkers (zoals doxazosine, tamsulosine) worden gebruikt bij hypertensie en BPH.</p>","image_url":"","wiki_title":"Alpha-1 adrenergic receptor","match":"alfa 1 receptor|alfa-1 receptor|alfa-1-receptor|α1-receptor|alfa1-receptor|alfa 1-receptor|α1 receptor","option_only":true},"alfa 2 receptor":{"title":"α2-adrenerge receptor","short":"De α2-receptor is een remmende adrenerge receptor (Gi), o.a. presynaptisch, die de afgifte van noradrenaline vermindert.","definition":"<p>De <strong>α2-adrenerge receptor</strong> is gekoppeld aan een Gi-eiwit en remt adenylaatcyclase (minder cAMP).</p><p>Hij zit onder meer <em>presynaptisch</em> op noradrenerge zenuwuiteinden, waar hij als negatieve terugkoppeling de afgifte van noradrenaline remt; centraal verlaagt dit de sympathische activiteit. Ook remt hij de insulineafgifte. Agonisten zoals clonidine worden gebruikt als antihypertensivum en sedativum.</p>","image_url":"","wiki_title":"Alpha-2 adrenergic receptor","match":"alfa 2 receptor|alfa-2 receptor|alfa-2-receptor|α2-receptor|alfa2-receptor|alfa 2-receptor|α2 receptor","option_only":true},"beta 1 receptor":{"title":"β1-adrenerge receptor","short":"De β1-receptor is een adrenerge receptor (Gs) vooral in het hart; activatie verhoogt hartfrequentie en contractiekracht en de reninesecretie.","definition":"<p>De <strong>β1-adrenerge receptor</strong> is gekoppeld aan een Gs-eiwit: activatie verhoogt cAMP en proteïnekinase A.</p><p>Hij zit vooral in het <em>hart</em>, waar hij hartfrequentie (positief chronotroop), contractiekracht (positief inotroop) en geleidingssnelheid verhoogt, en in de juxtaglomerulaire cellen van de nier, waar hij de <em>reninesecretie</em> stimuleert. Bètablokkers als metoprolol werken vooral hierop.</p>","image_url":"","wiki_title":"Beta-1 adrenergic receptor","match":"beta 1 receptor|beta-1 receptor|beta-1-receptor|bèta-1-receptor|β1-receptor|beta1-receptor|beta 1-receptor|β1 receptor","option_only":true},"beta 2 receptor":{"title":"β2-adrenerge receptor","short":"De β2-receptor is een adrenerge receptor (Gs) op gladde spier; activatie geeft bronchodilatatie en vasodilatatie in skeletspier.","definition":"<p>De <strong>β2-adrenerge receptor</strong> is via een Gs-eiwit gekoppeld aan cAMP-verhoging, wat in gladde spier <em>relaxatie</em> geeft.</p><p>Effecten: bronchodilatatie, vasodilatatie in skeletspier, relaxatie van de uterus, en metabool glycogenolyse in lever en spier en verschuiving van kalium de cel in. β2-agonisten (salbutamol, formoterol) worden gebruikt bij astma en COPD.</p>","image_url":"","wiki_title":"Beta-2 adrenergic receptor","match":"beta 2 receptor|beta-2 receptor|beta-2-receptor|bèta-2-receptor|β2-receptor|beta2-receptor|beta 2-receptor|β2 receptor","option_only":true},"serotonine":{"title":"Serotonine","short":"Serotonine (5-HT) is een monoamine uit tryptofaan; neurotransmitter voor stemming, slaap en eetlust en in de darm en bloedplaatjes actief.","definition":"<p><strong>Serotonine</strong> (5-hydroxytryptamine) wordt gemaakt uit het aminozuur <em>tryptofaan</em>. Het meeste zit in enterochromaffiene cellen van de darm en wordt in bloedplaatjes opgeslagen.</p><p>In het brein komen serotonerge neuronen uit de raphekernen van de hersenstam; ze beïnvloeden stemming, angst, slaap, eetlust en pijn. SSRI's remmen de heropname en worden bij depressie en angststoornissen gebruikt. In de darm stimuleert serotonine de motiliteit; perifeer veroorzaakt het vasoconstrictie of -dilatatie afhankelijk van het vaatbed.</p>","image_url":"","wiki_title":"Serotonin","match":"serotonine|5-ht|5-hydroxytryptamine|serotonin","option_only":true},"phenylethanolamine n-methyltransferase":{"title":"Fenylethanolamine-N-methyltransferase (PNMT)","short":"PNMT is het enzym in het bijniermerg dat noradrenaline omzet in adrenaline; het wordt gestimuleerd door cortisol.","definition":"<p><strong>PNMT</strong> (fenylethanolamine-N-methyltransferase) katalyseert de laatste stap van de catecholaminesynthese: de methylering van <em>noradrenaline tot adrenaline</em>.</p><p>De syntheseroute is tyrosine → L-DOPA → dopamine → noradrenaline → adrenaline. PNMT komt vooral voor in de chromaffiene cellen van het <em>bijniermerg</em>. Cortisol uit de omringende bijnierschors, dat via het portale vaatstelsel het merg bereikt, induceert PNMT.</p>","image_url":"","wiki_title":"Phenylethanolamine N-methyltransferase","match":"phenylethanolamine n-methyltransferase|fenylethanolamine-n-methyltransferase|phenylethanolamine-n-methyltransferase|pnmt","option_only":true},"glucose":{"title":"Glucose","short":"Glucose is een monosacharide (C₆H₁₂O₆) en de belangrijkste brandstof van het lichaam; de bloedspiegel wordt strak geregeld door insuline en glucagon.","definition":"<p><strong>Glucose</strong> is een hexose en de centrale brandstof van het metabolisme. Cellen breken het af via de glycolyse en daarna (aeroob) via de citroenzuurcyclus en oxidatieve fosforylering tot CO<sub>2</sub> en water, met vorming van ATP.</p><p>Het lichaam slaat glucose op als <em>glycogeen</em> in lever en spier. De bloedglucose (normaal nuchter ±4–6 mmol/L) wordt verlaagd door insuline en verhoogd door glucagon, adrenaline en cortisol. Het brein is sterk afhankelijk van glucose.</p>","image_url":"","wiki_title":"Glucose","match":"glucose|druivensuiker|bloedglucose","option_only":true},"vetzuren":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuren|vrije vetzuren|vetzuur|vetzuurverbranding|vetzuuroxidatie","option_only":true},"magnesium":{"title":"Magnesium","short":"Magnesium is een belangrijk intracellulair kation, cofactor van ATP-afhankelijke enzymen en nodig voor stabiele zenuw- en spierprikkelbaarheid.","definition":"<p><strong>Magnesium</strong> (Mg<sup>2+</sup>) zit vooral in bot en intracellulair. Het is cofactor van honderden enzymen, met name die met ATP werken, en stabiliseert de membraanpotentiaal.</p><p>Hypomagnesiëmie (o.a. door diuretica, PPI's, alcohol of diarree) geeft spierkrampen, tetanie, ritmestoornissen en kan hypokaliëmie en hypocalciëmie onderhouden (PTH-secretie daalt). Magnesiumsulfaat wordt gebruikt bij (pre-)eclampsie en torsade de pointes.</p>","image_url":"","wiki_title":"Magnesium in biology","match":"magnesium|mg2+|magnesiumsulfaat","option_only":true},"oestrogeen":{"title":"Oestrogeen","short":"Oestrogenen (vooral oestradiol) zijn vrouwelijke geslachtshormonen uit de ovaria die de geslachtskenmerken, cyclus en botdichtheid beïnvloeden.","definition":"<p><strong>Oestrogenen</strong> (oestradiol, oestron, oestriol) zijn steroïdhormonen die vooral door de granulosacellen in de ovariële follikel worden gemaakt, door aromatisering van androgenen. In de zwangerschap maakt de placenta veel oestriol.</p><p>Ze zorgen voor de vrouwelijke secundaire geslachtskenmerken, laten het endometrium prolifereren (folliculaire fase), geven rond de ovulatie positieve terugkoppeling (LH-piek) en beschermen botmassa. Na de menopauze daalt de spiegel, wat o.a. osteoporose bevordert.</p>","image_url":"","wiki_title":"Estrogen","match":"oestrogeen|oestrogenen|oestradiol|estradiol|estrogeen","option_only":true},"alcohol":{"title":"Alcohol (ethanol)","short":"Ethanol wordt in de lever afgebroken via acetaldehyde tot azijnzuur; overmatig gebruik schaadt lever, brein, hart en pancreas.","definition":"<p><strong>Ethanol</strong> wordt vooral in de lever geoxideerd door <em>alcoholdehydrogenase</em> tot acetaldehyde en daarna door aldehydedehydrogenase tot acetaat. Hierbij ontstaat veel NADH, wat de gluconeogenese remt (hypoglykemie) en vetstapeling in de lever bevordert.</p><p>Chronisch overmatig gebruik geeft leververvetting, alcoholische hepatitis en cirrose, pancreatitis, cardiomyopathie, hypertensie, neuropathie, thiaminetekort (Wernicke-Korsakov) en een verhoogd risico op verschillende kankers.</p>","image_url":"","wiki_title":"Alcohol (drug)","match":"alcohol|ethanol|alcoholgebruik|overmatig alcoholgebruik|alcoholmisbruik","option_only":true},"ductus thoracicus":{"title":"Ductus thoracicus","short":"De ductus thoracicus is het grootste lymfevat; hij voert de lymfe van het grootste deel van het lichaam af naar de linker veneuze hoek.","definition":"<p>De <strong>ductus thoracicus</strong> begint in de buik bij de cisterna chyli, loopt door de hiatus aorticus van het diafragma omhoog door het achterste mediastinum en mondt uit in de <em>linker veneuze hoek</em> (samenkomst v. jugularis interna en v. subclavia sinistra).</p><p>Hij draineert de lymfe van de benen, de buik (inclusief chylus met vetten uit de darm), de linker thoraxhelft, de linker arm en de linker kant van hoofd en hals. De rechter bovenkwadrant draineert via de ductus lymphaticus dexter.</p>","image_url":"","wiki_title":"Thoracic duct","match":"ductus thoracicus|borstbuis","option_only":true},"hersenstam":{"title":"Hersenstam","short":"De hersenstam (mesencephalon, pons, medulla oblongata) verbindt grote hersenen en ruggenmerg en bevat kernen van hersenzenuwen en centra voor ademhaling en circulatie.","definition":"<p>De <strong>hersenstam</strong> bestaat uit het mesencephalon (middenhersenen), de pons en de medulla oblongata. Alle opstijgende en afdalende banen tussen hersenen en ruggenmerg lopen erdoorheen.</p><p>Hij bevat de kernen van de hersenzenuwen III–XII, de formatio reticularis (bewustzijn, slaap-waakritme) en vitale centra voor ademhaling en hart- en vaatregulatie. Uitval van de hersenstam is daardoor snel levensbedreigend; hersenstamreflexen worden getest bij de vaststelling van hersendood.</p>","image_url":"","wiki_title":"Brainstem","match":"hersenstam|truncus cerebri|truncus encephali","option_only":true},"hypothalamus":{"title":"Hypothalamus","short":"De hypothalamus is het regelcentrum van de homeostase: hij stuurt hypofyse, autonoom zenuwstelsel, temperatuur, honger, dorst en circadiaan ritme.","definition":"<p>De <strong>hypothalamus</strong> is een klein deel van het diencephalon, onder de thalamus en rond de derde ventrikel. Hij is via het infundibulum verbonden met de hypofyse.</p><p>Hij maakt releasing- en inhibiting-hormonen (o.a. TRH, CRH, GnRH, GHRH, dopamine) die via het portale systeem de voorkwab sturen, en ADH en oxytocine die in de achterkwab worden afgegeven. Daarnaast regelt hij lichaamstemperatuur, honger en verzadiging, dorst, het slaap-waakritme (nucleus suprachiasmaticus) en het autonome zenuwstelsel.</p>","image_url":"","wiki_title":"Hypothalamus","match":"hypothalamus","option_only":true},"thalamus":{"title":"Thalamus","short":"De thalamus is het grote schakelstation in het diencephalon: vrijwel alle sensorische informatie (behalve reuk) wordt hier verwerkt op weg naar de cortex.","definition":"<p>De <strong>thalamus</strong> is een paarige, eivormige kern in het diencephalon aan weerszijden van de derde ventrikel. Hij bestaat uit veel subkernen met elk een eigen corticale projectie.</p><p>Sensorische banen (somatosensoriek via de VPL/VPM, zien via het corpus geniculatum laterale, horen via het corpus geniculatum mediale) schakelen hier om naar de cortex. Ook motorische lussen van basale kernen en cerebellum lopen via de thalamus, en hij speelt een rol bij bewustzijn en aandacht.</p>","image_url":"","wiki_title":"Thalamus","match":"thalamus","option_only":true},"ruggenmerg":{"title":"Ruggenmerg","short":"Het ruggenmerg verbindt de hersenen met de rest van het lichaam; het bevat banen in de witte stof en neuronen voor reflexen in de grijze stof.","definition":"<p>Het <strong>ruggenmerg</strong> (medulla spinalis) loopt in het wervelkanaal van het foramen magnum tot ongeveer L1–L2 (conus medullaris), waarna de cauda equina volgt. Het geeft 31 paar spinale zenuwen af.</p><p>In dwarsdoorsnede ligt de vlindervormige <em>grijze stof</em> (voorhoorn: motorneuronen; achterhoorn: sensorische schakeling) binnenin, omgeven door <em>witte stof</em> met opstijgende (bijv. achterstrengen, tractus spinothalamicus) en afdalende banen (tractus corticospinalis).</p>","image_url":"","wiki_title":"Spinal cord","match":"ruggenmerg|medulla spinalis","option_only":true},"n. oculomotorius":{"title":"N. oculomotorius (III)","short":"De n. oculomotorius (III) innerveert de meeste uitwendige oogspieren, de ooglidheffer en (parasympathisch) de pupilvernauwer en accommodatie.","definition":"<p>De <strong>n. oculomotorius</strong> komt uit het mesencephalon en innerveert de m. rectus superior, inferior en medialis, de m. obliquus inferior en de m. levator palpebrae superioris.</p><p>Parasympathische vezels (uit de kern van Edinger-Westphal, schakeling in het ganglion ciliare) innerveren de m. sphincter pupillae (miosis) en de m. ciliaris (accommodatie). Uitval geeft een oog dat naar buiten-onder staat, ptosis en een wijde, lichtstijve pupil.</p>","image_url":"","wiki_title":"Oculomotor nerve","match":"n. oculomotorius|nervus oculomotorius|n. iii|hersenzenuw iii","option_only":true},"n. trochlearis":{"title":"N. trochlearis (IV)","short":"De n. trochlearis (IV) innerveert alleen de m. obliquus superior; hij is de enige hersenzenuw die dorsaal uit de hersenstam treedt.","definition":"<p>De <strong>n. trochlearis</strong> is de dunste hersenzenuw en de enige die aan de <em>dorsale</em> zijde van de hersenstam uittreedt (onder de colliculi inferiores) en kruist.</p><p>Hij innerveert de <em>m. obliquus superior</em>, die het oog vooral naar beneden draait als het naar binnen kijkt, en intorsie geeft. Uitval geeft verticale dubbelbeelden, vooral bij naar beneden kijken (traplopen, lezen), met compenserende hoofdkanteling naar de gezonde kant.</p>","image_url":"","wiki_title":"Trochlear nerve","match":"n. trochlearis|nervus trochlearis|n. iv|hersenzenuw iv","option_only":true},"n. trigeminus":{"title":"N. trigeminus (V)","short":"De n. trigeminus (V) is de gevoelszenuw van het gezicht (drie takken: V1, V2, V3) en de motorische zenuw van de kauwspieren.","definition":"<p>De <strong>n. trigeminus</strong> treedt uit de pons en splitst in het ganglion trigeminale in drie takken: n. ophthalmicus (V1), n. maxillaris (V2) en n. mandibularis (V3).</p><p>Sensibel verzorgt hij het gezicht, het hoornvlies (afferent deel van de cornea-reflex), mond- en neusslijmvlies en de voorste twee derde van de tong (aanraking). De motorische vezels (alleen in V3) innerveren de kauwspieren (m. masseter, m. temporalis, mm. pterygoidei).</p>","image_url":"","wiki_title":"Trigeminal nerve","match":"n. trigeminus|nervus trigeminus|n. v|hersenzenuw v","option_only":true},"nervus glossopharyngeus":{"title":"N. glossopharyngeus (IX)","short":"De n. glossopharyngeus (IX) verzorgt smaak en gevoel van het achterste derde van de tong en de keel, en ontvangt informatie van de sinus caroticus.","definition":"<p>De <strong>n. glossopharyngeus</strong> treedt uit de medulla oblongata en verlaat de schedel via het foramen jugulare.</p><p>Functies: sensibiliteit en smaak van het achterste derde van de tong, gevoel van de farynx (afferent deel van de braakreflex) en het middenoor, en afferente informatie van de baroreceptoren in de <em>sinus caroticus</em> en chemoreceptoren in het glomus caroticum. Motorisch innerveert hij de m. stylopharyngeus en parasympathisch de glandula parotidea (via het ganglion oticum).</p>","image_url":"","wiki_title":"Glossopharyngeal nerve","match":"nervus glossopharyngeus|n. glossopharyngeus|n. ix|hersenzenuw ix","option_only":true},"epifyse":{"title":"Epifyse","short":"De epifyse is het uiteinde van een pijpbeen, of de pijnappelklier (glandula pinealis) die melatonine maakt — het woord heeft twee betekenissen.","definition":"<p>Bij een <strong>pijpbeen</strong> is de epifyse het verbrede uiteinde, bedekt met gewrichtskraakbeen. Bij kinderen ligt tussen epifyse en metafyse de groeischijf (epifysairschijf), waar het bot in de lengte groeit; na de puberteit sluit die.</p><p>In de hersenen wordt met <strong>epifyse</strong> ook de <em>glandula pinealis</em> (pijnappelklier) bedoeld, een onderdeel van de epithalamus dat in het donker melatonine afgeeft en zo het dag-nachtritme ondersteunt.</p>","image_url":"","wiki_title":"Epiphysis","match":"epifyse|epiphysis","option_only":true},"hypertensie":{"title":"Hypertensie","short":"Hypertensie is een blijvend verhoogde bloeddruk (≥140/90 mmHg op het spreekuur); een belangrijke risicofactor voor hart- en vaatziekten.","definition":"<p>Bij <strong>hypertensie</strong> is de bloeddruk herhaaldelijk verhoogd: op het spreekuur ≥140/90 mmHg. Meestal is er geen aanwijsbare oorzaak (<em>primaire/essentiële</em> hypertensie); bij een minderheid is er een secundaire oorzaak, zoals nierziekte, nierarteriestenose, hyperaldosteronisme of feochromocytoom.</p><p>Hypertensie geeft meestal geen klachten, maar beschadigt op termijn vaten en organen: linkerventrikelhypertrofie, hartfalen, CVA, nierschade en retinopathie. Behandeling: leefstijl (zout, gewicht, beweging, alcohol) en medicatie (o.a. diuretica, ACE-remmers/ARB's, calciumantagonisten).</p>","image_url":"","wiki_title":"Hypertension","match":"hypertensie|hoge bloeddruk|arteriële hypertensie","option_only":true},"myocardinfarct":{"title":"Myocardinfarct","short":"Bij een myocardinfarct sterft hartspierweefsel af doordat een kransslagader (meestal door een trombus op een gescheurde plaque) afsluit.","definition":"<p>Een <strong>myocardinfarct</strong> ontstaat meestal doordat een atherosclerotische plaque in een coronairarterie scheurt, waarna een trombus het vat (deels) afsluit. Het hartspierweefsel achter de afsluiting raakt ischemisch en gaat na 20–30 minuten necrotisch.</p><p>Klachten: drukkende pijn op de borst, uitstralend naar arm, kaak of rug, met zweten, misselijkheid en benauwdheid. Diagnose op basis van klachten, ECG (ST-elevatie of niet) en een stijging van troponine. Complicaties zijn ritmestoornissen, hartfalen en mechanische complicaties. Snelle reperfusie (PCI) is cruciaal.</p>","image_url":"","wiki_title":"Myocardial infarction","match":"myocardinfarct|hartinfarct|acuut myocardinfarct|ami","option_only":true},"diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes mellitus|diabetes|suikerziekte|diabetes mellitus type 2|diabetes mellitus type 1|diabetes mellitus 2","option_only":true},"obesitas":{"title":"Obesitas","short":"Obesitas is ernstig overgewicht (BMI ≥30 kg/m²) met verhoogd risico op diabetes type 2, hart- en vaatziekten, artrose en bepaalde kankers.","definition":"<p>Bij <strong>obesitas</strong> is er een overmaat aan lichaamsvet, gedefinieerd als een <em>BMI ≥30 kg/m²</em>. Vooral vet in de buik (grote middelomtrek, visceraal vet) is metabool ongunstig.</p><p>Obesitas verhoogt het risico op insulineresistentie en diabetes type 2, hypertensie, dyslipidemie, hart- en vaatziekten, slaapapneu, leververvetting, artrose en verschillende vormen van kanker. Oorzaken zijn een combinatie van leefstijl, omgeving, genetische aanleg en soms medicatie of hormonale ziekten.</p>","image_url":"","wiki_title":"Obesity","match":"obesitas|ernstig overgewicht|adipositas","option_only":true},"erytheem":{"title":"Erytheem","short":"Erytheem is roodheid van de huid door verwijding van de bloedvaatjes in de dermis; bij druk verbleekt het (wegdrukbaar).","definition":"<p><strong>Erytheem</strong> is een rode verkleuring van de huid door <em>hyperemie</em>: verwijde capillairen in de dermis. Kenmerkend is dat het bij druk (glasspateltest) wegdrukbaar is, in tegenstelling tot een bloeding in de huid (purpura, petechiën).</p><p>Het is een efflorescentie die voorkomt bij ontsteking, infectie (bijv. erysipelas), allergische reacties, zonverbranding en bij veel huidziekten.</p>","image_url":"","wiki_title":"Erythema","match":"erytheem|erythema|roodheid","option_only":true},"epilepsie":{"title":"Epilepsie","short":"Epilepsie is een hersenaandoening met herhaalde, niet-uitgelokte epileptische aanvallen door abnormale, synchrone ontladingen van neuronen.","definition":"<p>Bij <strong>epilepsie</strong> heeft iemand de neiging tot herhaalde epileptische aanvallen. Een aanval ontstaat door een plotselinge, overmatige en gesynchroniseerde ontlading van groepen neuronen.</p><p>Aanvallen kunnen focaal beginnen (in één hersengebied; met of zonder bewustzijnsdaling) of gegeneraliseerd (beide hemisferen; bijv. tonisch-klonische aanvallen of absences). Oorzaken: genetisch, structureel (litteken, tumor, ontwikkelingsstoornis), infectieus, metabool of onbekend. Diagnostiek met anamnese/heteroanamnese, EEG en MRI.</p>","image_url":"","wiki_title":"Epilepsy","match":"epilepsie","option_only":true},"maagcarcinoom":{"title":"Maagcarcinoom","short":"Een maagcarcinoom is een kwaadaardige tumor (meestal adenocarcinoom) van de maag; risicofactoren zijn o.a. H. pylori, roken en zoutrijke voeding.","definition":"<p>Het <strong>maagcarcinoom</strong> is meestal een adenocarcinoom, uitgaand van het klierepitheel. Het intestinale type ontstaat via een reeks van chronische (H. pylori-)gastritis, atrofie, intestinale metaplasie en dysplasie; het diffuse type (zegelringcellen) infiltreert de wand zonder duidelijke massa (linitis plastica).</p><p>Klachten komen vaak laat: verminderde eetlust, vroege verzadiging, gewichtsverlies, epigastrische pijn, anemie of slikklachten. Metastasen kunnen zich manifesteren als een klier van Virchow (links supraclaviculair) of ovariummetastasen (Krukenberg).</p>","image_url":"","wiki_title":"Stomach cancer","match":"maagcarcinoom|maagkanker|adenocarcinoom van de maag","option_only":true},"diarree":{"title":"Diarree","short":"Diarree is het vaker dan normaal (≥3x per dag) produceren van brijige tot waterdunne ontlasting.","definition":"<p><strong>Diarree</strong> betekent een verhoogde frequentie (meestal ≥3 keer per dag) en verminderde consistentie van de ontlasting. Acute diarree (&lt;2 weken) is meestal infectieus (virussen zoals norovirus, bacteriën, parasieten).</p><p>Mechanismen: <em>secretoir</em> (bijv. door toxines zoals choleratoxine), <em>osmotisch</em> (bijv. lactose-intolerantie, laxantia), <em>inflammatoir</em> (bijv. IBD, invasieve bacteriën, met bloed en slijm) en versnelde motiliteit. Het belangrijkste risico is uitdroging en elektrolytverlies.</p>","image_url":"","wiki_title":"Diarrhea","match":"diarree","option_only":true},"reflex":{"title":"Reflex","short":"Een reflex is een snelle, onwillekeurige, stereotiepe reactie op een prikkel, via een vaste zenuwbaan (reflexboog).","definition":"<p>Een <strong>reflex</strong> is een automatische reactie op een sensorische prikkel. De onderdelen van de reflexboog zijn: receptor, afferente zenuw, schakelcentrum (ruggenmerg of hersenstam), efferente zenuw en effector (spier of klier).</p><p>Voorbeelden zijn de kniepeesreflex (monosynaptisch), de terugtrekreflex en autonome reflexen zoals de baroreceptorreflex. Reflexen kunnen aangeboren zijn of, zoals bij de conditionering van Pavlov, aangeleerd (geconditioneerde reflex).</p>","image_url":"","wiki_title":"Reflex","match":"reflex|reflexen","option_only":true},"lever":{"title":"Lever","short":"De lever is de grootste klier van het lichaam: hij regelt stofwisseling van suikers, vetten en eiwitten, maakt gal en eiwitten (o.a. albumine, stollingsfactoren) en ontgift stoffen.","definition":"<p>De <strong>lever</strong> ligt rechtsboven in de buik en krijgt bloed uit de a. hepatica en (voor ±75%) uit de <em>v. portae</em>, met voedingsstoffen uit de darm.</p><p>Functies: opslag en afgifte van glucose (glycogeen, gluconeogenese), vet- en cholesterolmetabolisme, aanmaak van plasma-eiwitten (albumine, stollingsfactoren), ureumvorming, galproductie, afbraak van bilirubine en ontgifting van geneesmiddelen en alcohol. Functionele eenheden zijn de leverlobjes met hepatocyten rond sinusoïden.</p>","image_url":"","wiki_title":"Liver","match":"lever|hepar","option_only":true},"maag":{"title":"Maag","short":"De maag slaat voedsel tijdelijk op, mengt het met maagzuur en pepsine en geeft het geleidelijk af aan het duodenum.","definition":"<p>De <strong>maag</strong> bestaat uit cardia, fundus, corpus, antrum en pylorus. Het slijmvlies bevat klieren met <em>pariëtale cellen</em> (zoutzuur en intrinsieke factor), <em>hoofdcellen</em> (pepsinogeen), slijmcellen en endocriene cellen (o.a. G-cellen met gastrine in het antrum).</p><p>De maag doodt micro-organismen, start de eiwitvertering en mengt voedsel tot chymus. Intrinsieke factor is nodig voor opname van vitamine B12 in het terminale ileum.</p>","image_url":"","wiki_title":"Stomach","match":"maag|gaster|ventriculus","option_only":true},"pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"pancreas|alvleesklier","option_only":true},"t-cellen":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t-cellen|t cellen|t-lymfocyten|t-cel|t-lymfocyt|t cel","option_only":true},"dendritische cellen":{"title":"Dendritische cellen","short":"Dendritische cellen zijn de belangrijkste antigeenpresenterende cellen: ze nemen antigeen op in weefsels en activeren naïeve T-cellen in de lymfeklier.","definition":"<p><strong>Dendritische cellen</strong> zitten in weefsels die in contact staan met de buitenwereld, zoals huid (Langerhanscellen) en slijmvliezen. Met hun uitlopers nemen ze antigenen op.</p><p>Na activatie (bijv. via Toll-like receptoren) migreren ze naar de lymfeklier, waar ze antigeenfragmenten op MHC-I en MHC-II presenteren, met costimulerende moleculen. Ze zijn de enige cellen die effectief <em>naïeve T-cellen</em> activeren en vormen zo de brug tussen aangeboren en verworven afweer.</p>","image_url":"","wiki_title":"Dendritic cell","match":"dendritische cellen|dendritische cel|langerhanscellen","option_only":true},"samenvatten":{"title":"Samenvatten (gesprekstechniek)","short":"Samenvatten is een gesprekstechniek waarbij de arts de kern van wat de patiënt heeft verteld kort in eigen woorden teruggeeft, om te checken en te structureren.","definition":"<p>Bij <strong>samenvatten</strong> vat de arts meerdere uitspraken of een heel gespreksdeel van de patiënt kort samen. Het doel is te controleren of de informatie goed begrepen is, overzicht te geven en het gesprek te structureren, bijvoorbeeld als afsluiting van een fase voordat een nieuw onderwerp begint.</p><p>Samenvatten gaat over de inhoud van een groter deel van het gesprek; het verschilt daarin van parafraseren, dat één uitspraak teruggeeft.</p>","image_url":"","wiki_title":"","match":"samenvatten|samenvatting geven","option_only":true},"parafraseren":{"title":"Parafraseren (gesprekstechniek)","short":"Parafraseren is het in eigen woorden teruggeven van de inhoud van één uitspraak van de patiënt, om te laten merken dat je luistert en te checken of je het goed begrijpt.","definition":"<p>Bij <strong>parafraseren</strong> herhaalt de arts de <em>inhoud</em> van wat de patiënt net zei in eigen, vaak kortere woorden (bijvoorbeeld: “U heeft dus vooral ’s nachts last”). Het is een vorm van actief luisteren.</p><p>Parafraseren nodigt de patiënt uit om verder te vertellen of te corrigeren. Het verschilt van het reflecteren van gevoelens, dat zich richt op de emotie achter de woorden.</p>","image_url":"","wiki_title":"","match":"parafraseren|parafrase","option_only":true},"agenderen":{"title":"Agenderen (gesprekstechniek)","short":"Agenderen is aan het begin van een consult samen met de patiënt vaststellen welke onderwerpen besproken worden.","definition":"<p>Bij <strong>agenderen</strong> inventariseert de arts aan het begin van het gesprek welke vragen en klachten de patiënt wil bespreken, en vult die aan met eigen punten (bijv. uitslagen of controles). Samen wordt besloten wat er in dit consult aan bod komt en in welke volgorde.</p><p>Het voorkomt dat belangrijke punten aan het eind van het gesprek nog opduiken (‘deurknopvragen’) en geeft het consult structuur.</p>","image_url":"","wiki_title":"","match":"agenderen|agenda bespreken|agenda opstellen","option_only":true},"gesprekskader bespreken":{"title":"Gesprekskader bespreken","short":"Het gesprekskader bespreken betekent aan het begin van een gesprek uitleggen wat het doel, de duur en de opbouw van het gesprek zijn.","definition":"<p>Bij het <strong>bespreken van het gesprekskader</strong> vertelt de arts aan het begin wat de aanleiding en het doel van het gesprek zijn, hoeveel tijd er is, en hoe het gesprek ongeveer verloopt (bijvoorbeeld eerst vragen stellen, dan onderzoek, dan bespreken).</p><p>Het geeft de patiënt duidelijkheid en houvast, en vormt samen met agenderen het startpunt van een gestructureerd consult.</p>","image_url":"","wiki_title":"","match":"gesprekskader bespreken|gesprekskader|kader schetsen|het gesprekskader aangeven","option_only":true},"hardop denken":{"title":"Hardop denken","short":"Hardop denken is het voor de patiënt uitspreken van je overwegingen tijdens onderzoek of besluitvorming, zodat de patiënt kan meekijken en meedenken.","definition":"<p>Bij <strong>hardop denken</strong> verwoordt de arts wat hij of zij doet en overweegt, bijvoorbeeld tijdens het lichamelijk onderzoek (“ik voel nu aan uw buik of de lever vergroot is”) of bij het afwegen van mogelijke oorzaken.</p><p>Het maakt het klinisch redeneren transparant, vermindert onzekerheid bij de patiënt en ondersteunt gedeelde besluitvorming.</p>","image_url":"","wiki_title":"","match":"hardop denken|hardop-denken","option_only":true},"tia":{"title":"Transient ischaemic attack (TIA)","short":"Een TIA is een kortdurende uitval van een hersenfunctie door tijdelijke ischemie, zonder blijvend infarct; een belangrijk waarschuwingssignaal voor een herseninfarct.","definition":"<p>Bij een <strong>TIA</strong> (transient ischaemic attack) ontstaan plotseling focale neurologische klachten (bijv. halfzijdige verlamming, afasie, monoculaire blindheid) die meestal binnen enkele minuten tot een uur volledig verdwijnen, zonder infarct op beeldvorming.</p><p>De oorzaak is meestal een embolie (vanuit de carotis of het hart, bijv. bij boezemfibrilleren) of een kleine-vatenafwijking. Na een TIA is het risico op een herseninfarct in de eerste dagen sterk verhoogd; snelle analyse en secundaire preventie (antistolling of plaatjesremmers, statine, bloeddruk) zijn nodig.</p>","image_url":"","wiki_title":"Transient ischemic attack","match":"tia|transient ischaemic attack|transient ischemic attack","option_only":true},"colon":{"title":"Colon (dikke darm)","short":"Het colon is de dikke darm van caecum tot rectum; het resorbeert water en zouten en dikt de ontlasting in.","definition":"<p>Het <strong>colon</strong> bestaat uit caecum, colon ascendens, transversum, descendens en sigmoideum, gevolgd door het rectum. Kenmerkend zijn taeniae coli, haustra en appendices epiploicae. Het slijmvlies heeft geen villi maar wel diepe crypten met veel slijmbekercellen. Het colon resorbeert water en elektrolyten, en de darmflora fermenteert vezels tot korteketenvetzuren.</p>","image_url":"","wiki_title":"Large intestine","match":"colon|dikke darm|dikkedarm","option_only":true},"dikke darm":{"title":"Dikke darm","short":"De dikke darm (caecum, colon en rectum) resorbeert water en zouten en vormt de ontlasting.","definition":"<p>De <strong>dikke darm</strong> loopt van de ileocaecaalklep tot de anus en bestaat uit caecum met appendix, colon en rectum. Hij resorbeert vooral water en natrium, en bevat een rijke bacteriële flora die onverteerbare vezels fermenteert en vitamine K maakt. Het slijmvlies is vlak met crypten en veel slijmbekercellen.</p>","image_url":"","wiki_title":"Large intestine","match":"dikke darm","option_only":true},"dunne darm":{"title":"Dunne darm","short":"De dunne darm (duodenum, jejunum, ileum) is het belangrijkste deel van het maag-darmkanaal voor vertering en opname van voedingsstoffen.","definition":"<p>De <strong>dunne darm</strong> is enkele meters lang en bestaat uit duodenum, jejunum en ileum. Kringplooien, villi en microvilli vergroten het oppervlak enorm. Hier worden koolhydraten, eiwitten en vetten verteerd door pancreasenzymen en brush-border-enzymen en opgenomen; in het terminale ileum worden ook vitamine B12 en galzouten geresorbeerd.</p>","image_url":"","wiki_title":"Small intestine","match":"dunne darm|intestinum tenue","option_only":true},"oesophagus":{"title":"Oesophagus (slokdarm)","short":"De oesophagus is de gespierde buis die voedsel van de keelholte naar de maag vervoert.","definition":"<p>De <strong>oesophagus</strong> is ongeveer 25 cm lang en loopt achter de trachea door het mediastinum en via de hiatus oesophageus van het diafragma naar de maag. Het slijmvlies is meerlagig onverhoornd plaveiselepitheel. Het bovenste deel bevat dwarsgestreepte, het onderste deel gladde spier. De onderste slokdarmsfincter voorkomt terugstroom van maaginhoud.</p>","image_url":"","wiki_title":"Esophagus","match":"oesophagus|slokdarm|oesofagus|esophagus","option_only":true},"vitamine d":{"title":"Vitamine D","short":"Vitamine D bevordert de opname van calcium en fosfaat uit de darm en is nodig voor sterke botten.","definition":"<p><strong>Vitamine D</strong> wordt in de huid onder invloed van UVB-licht gemaakt of via de voeding opgenomen. De lever zet het om in 25-OH-vitamine D en de nier (onder invloed van PTH) in het actieve 1,25-(OH)₂-vitamine D (calcitriol). Calcitriol verhoogt de opname van calcium en fosfaat in de darm. Tekort geeft rachitis bij kinderen en osteomalacie bij volwassenen.</p>","image_url":"","wiki_title":"Vitamin D","match":"vitamine d|calcitriol|colecalciferol|vitamine d3","option_only":true},"albumine":{"title":"Albumine","short":"Albumine is het meest voorkomende plasma-eiwit; het houdt vocht in de bloedbaan (colloïd-osmotische druk) en vervoert veel stoffen.","definition":"<p><strong>Albumine</strong> wordt in de lever gemaakt. Het zorgt voor het grootste deel van de colloïd-osmotische druk en bindt o.a. calcium, bilirubine, vrije vetzuren, hormonen en geneesmiddelen. Een laag albumine komt voor bij leverziekte, nefrotisch syndroom, ondervoeding en ontsteking (negatief acutefase-eiwit) en kan oedeem geven.</p>","image_url":"","wiki_title":"Human serum albumin","match":"albumine|serumalbumine","option_only":true},"aminozuren":{"title":"Aminozuren","short":"Aminozuren zijn de bouwstenen van eiwitten; ze bevatten een aminogroep, een carboxylgroep en een specifieke zijketen.","definition":"<p>Er zijn 20 standaard-<strong>aminozuren</strong>, waarvan 9 essentieel (ze moeten uit de voeding komen). Ze worden via peptidebindingen aan elkaar gekoppeld tot eiwitten. Daarnaast zijn ze grondstof voor o.a. neurotransmitters, hormonen, heem en nucleotiden, en kunnen ze worden afgebroken voor energie of gluconeogenese; de stikstof wordt dan via de ureumcyclus afgevoerd.</p>","image_url":"","wiki_title":"Amino acid","match":"aminozuren|aminozuur","option_only":true},"insuline":{"title":"Insuline","short":"Insuline is het hormoon uit de bètacellen van de pancreas dat de bloedglucose verlaagt en opbouwprocessen stimuleert.","definition":"<p><strong>Insuline</strong> wordt afgegeven als de glucose stijgt. Het bevordert de opname van glucose in spier en vet (via GLUT4), de opslag als glycogeen en vet, en de eiwitsynthese, en remt gluconeogenese, glycogenolyse en lipolyse. Het wordt gemaakt als proinsuline; de afsplitsing van C-peptide maakt het actief. Als geneesmiddel is het onmisbaar bij diabetes type 1.</p>","image_url":"","wiki_title":"Insulin","match":"insuline|insulin","option_only":true},"glucagon":{"title":"Glucagon","short":"Glucagon is het hormoon uit de alfacellen van de pancreas dat de bloedglucose verhoogt, vooral via de lever.","definition":"<p><strong>Glucagon</strong> wordt afgegeven bij een lage glucose en bij eiwitrijke maaltijden. In de lever stimuleert het glycogenolyse, gluconeogenese en ketogenese via cAMP. Het is daarmee de tegenspeler van insuline. Glucagon kan intramusculair worden gegeven bij een ernstige hypoglykemie als iemand niet kan eten.</p>","image_url":"","wiki_title":"Glucagon","match":"glucagon","option_only":true},"cortisol":{"title":"Cortisol","short":"Cortisol is het belangrijkste glucocorticoïd uit de bijnierschors; het is een stresshormoon met effecten op stofwisseling en afweer.","definition":"<p><strong>Cortisol</strong> wordt gemaakt in de zona fasciculata onder invloed van ACTH, met een dagritme (hoog in de ochtend). Het verhoogt de bloedglucose (gluconeogenese), breekt eiwitten af, remt ontsteking en afweer en ondersteunt de bloeddruk. Overmaat geeft het syndroom van Cushing, tekort bijnierinsufficiëntie (ziekte van Addison).</p>","image_url":"","wiki_title":"Cortisol","match":"cortisol|hydrocortison","option_only":true},"acth":{"title":"ACTH (corticotropine)","short":"ACTH is een hormoon uit de hypofysevoorkwab dat de bijnierschors aanzet tot de productie van cortisol.","definition":"<p><strong>ACTH</strong> ontstaat door splitsing van het voorlopereiwit POMC, waaruit ook MSH ontstaat (daardoor kan veel ACTH hyperpigmentatie geven). De afgifte wordt gestimuleerd door CRH uit de hypothalamus en geremd door cortisol (negatieve terugkoppeling). Het stimuleert vooral de zona fasciculata en heeft een groeibevorderend effect op de bijnierschors.</p>","image_url":"","wiki_title":"Adrenocorticotropic hormone","match":"acth|corticotropine|adrenocorticotroop hormoon","option_only":true},"prolactine":{"title":"Prolactine","short":"Prolactine is een hormoon uit de hypofysevoorkwab dat de melkproductie stimuleert; dopamine remt de afgifte.","definition":"<p><strong>Prolactine</strong> wordt gemaakt door lactotrofe cellen van de hypofysevoorkwab. Het stimuleert de borstklier tot melkproductie; zuigen aan de tepel verhoogt de afgifte. Dopamine uit de hypothalamus remt de afgifte tonisch. Een verhoogd prolactine (bijv. door een prolactinoom of dopamineblokkerende middelen) remt GnRH, met cyclusstoornissen, galactorroe en libidoverlies.</p>","image_url":"","wiki_title":"Prolactin","match":"prolactine|prl","option_only":true},"adrenaline":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"adrenaline|epinefrine|epinephrine","option_only":true},"dopamine":{"title":"Dopamine","short":"Dopamine is een catecholamine-neurotransmitter, belangrijk voor motoriek, beloning en de remming van prolactine.","definition":"<p><strong>Dopamine</strong> wordt gemaakt uit tyrosine via L-DOPA. Belangrijke dopaminerge banen zijn de nigrostriatale baan (motoriek; verlies bij Parkinson), de mesolimbische en mesocorticale banen (beloning, motivatie, psychose) en de tubero-infundibulaire baan (remming van prolactine). Antipsychotica blokkeren D2-receptoren.</p>","image_url":"","wiki_title":"Dopamine","match":"dopamine","option_only":true},"stikstofoxide":{"title":"Stikstofoxide (NO)","short":"Stikstofoxide (NO) is een gasvormige signaalstof uit het endotheel die gladde spier ontspant en zo vaten verwijdt.","definition":"<p><strong>NO</strong> wordt gemaakt uit arginine door NO-synthase. In het endotheel ontstaat het o.a. door schuifspanning en acetylcholine; het diffundeert naar de gladde spiercel, activeert guanylaatcyclase en verhoogt cGMP, wat relaxatie geeft. NO remt ook de plaatjesaggregatie. Nitraten en PDE5-remmers versterken deze route.</p>","image_url":"","wiki_title":"Nitric oxide","match":"stikstofoxide|stikstofmonoxide|no|nitric oxide","option_only":true},"osteoclast":{"title":"Osteoclast","short":"Een osteoclast is een grote, meerkernige cel die botweefsel afbreekt (botresorptie).","definition":"<p><strong>Osteoclasten</strong> ontstaan uit de monocyt-macrofaaglijn door fusie van voorlopercellen. Ze hechten aan het botoppervlak en vormen een afgesloten ruimte onder een geplooide rand (ruffled border), waarin ze zuur en enzymen (o.a. cathepsine K) uitscheiden. Ze worden geactiveerd via RANKL en geremd door osteoprotegerine en calcitonine; bisfosfonaten remmen hun werking.</p>","image_url":"","wiki_title":"Osteoclast","match":"osteoclast|osteoclasten","option_only":true},"a. mesenterica inferior":{"title":"A. mesenterica inferior","short":"De a. mesenterica inferior voorziet het distale derde van het colon transversum, het colon descendens, sigmoïd en bovenste rectum.","definition":"<p>De <strong>a. mesenterica inferior</strong> ontspringt ter hoogte van L3 uit de aorta abdominalis. Haar takken zijn de a. colica sinistra, de aa. sigmoideae en de a. rectalis superior. Via de arcade van Riolan en de marginale arterie (van Drummond) staat ze in verbinding met de a. mesenterica superior.</p>","image_url":"","wiki_title":"Inferior mesenteric artery","match":"a. mesenterica inferior|arteria mesenterica inferior","option_only":true},"a. thyroidea inferior":{"title":"A. thyroidea inferior","short":"De a. thyroidea inferior is een tak van de truncus thyrocervicalis die de onderpool van de schildklier en de bijschildklieren voorziet.","definition":"<p>De <strong>a. thyroidea inferior</strong> komt uit de truncus thyrocervicalis (tak van de a. subclavia) en loopt achter de a. carotis naar de schildklier. Ze voorziet ook de bijschildklieren. Vlak bij de schildklier kruist ze de n. laryngeus recurrens, waar de chirurg bij een thyreoïdectomie extra op moet letten.</p>","image_url":"","wiki_title":"Inferior thyroid artery","match":"a. thyroidea inferior|arteria thyroidea inferior","option_only":true},"truncus brachiocephalicus":{"title":"Truncus brachiocephalicus","short":"De truncus brachiocephalicus is de eerste en grootste tak van de aortaboog en splitst in de rechter a. subclavia en a. carotis communis.","definition":"<p>De <strong>truncus brachiocephalicus</strong> ontspringt als eerste tak van de arcus aortae, achter het manubrium sterni. Ter hoogte van het rechter sternoclaviculaire gewricht splitst hij in de a. subclavia dextra en a. carotis communis dextra. Links ontbreekt zo'n stam: daar ontspringen de a. carotis communis en a. subclavia apart uit de aortaboog.</p>","image_url":"","wiki_title":"Brachiocephalic artery","match":"truncus brachiocephalicus|a. anonyma","option_only":true},"nervus vagus":{"title":"N. vagus (X)","short":"De n. vagus (X) is de belangrijkste parasympathische zenuw; hij innerveert hart, longen en het maag-darmkanaal tot het distale colon transversum.","definition":"<p>De <strong>n. vagus</strong> verlaat de schedel via het foramen jugulare en loopt in de halsvaatschede omlaag. Hij levert parasympathische vezels aan hart (vertraging), luchtwegen en darm, motorische vezels aan farynx en larynx (o.a. via de n. laryngeus recurrens) en sensibele informatie uit de inwendige organen, zoals van baroreceptoren in de aortaboog.</p>","image_url":"","wiki_title":"Vagus nerve","match":"nervus vagus|n. vagus|vagus|hersenzenuw x","option_only":true},"n. facialis":{"title":"N. facialis (VII)","short":"De n. facialis (VII) innerveert de mimische spieren en verzorgt ook smaak (voorste 2/3 tong), traan- en speekselsecretie.","definition":"<p>De <strong>n. facialis</strong> treedt uit bij de brughoek, loopt door het os temporale (canalis facialis) en verlaat de schedel via het foramen stylomastoideum; daarna splitst hij zich in de glandula parotidea in vijf takken. Naast de mimische spieren innerveert hij de m. stapedius. Bij een perifere facialisparese is de hele gezichtshelft verlamd, inclusief het voorhoofd.</p>","image_url":"","wiki_title":"Facial nerve","match":"n. facialis|nervus facialis|hersenzenuw vii|aangezichtszenuw","option_only":true},"n. accessorius":{"title":"N. accessorius (XI)","short":"De n. accessorius (XI) innerveert de m. sternocleidomastoideus en m. trapezius.","definition":"<p>De spinale wortels van de <strong>n. accessorius</strong> komen uit het bovenste halsmerg, gaan omhoog door het foramen magnum en verlaten de schedel via het foramen jugulare. In de laterale halsdriehoek loopt de zenuw oppervlakkig, waar hij kwetsbaar is bij lymfeklierbiopten. Uitval geeft zwakte bij het optrekken van de schouder en het draaien van het hoofd.</p>","image_url":"","wiki_title":"Accessory nerve","match":"n. accessorius|nervus accessorius|hersenzenuw xi","option_only":true},"n. hypoglossus":{"title":"N. hypoglossus (XII)","short":"De n. hypoglossus (XII) innerveert de tongspieren.","definition":"<p>De <strong>n. hypoglossus</strong> komt uit de medulla oblongata, verlaat de schedel via het canalis hypoglossi en loopt onder de mandibula naar de tong. Hij innerveert alle intrinsieke en de meeste extrinsieke tongspieren. Bij uitval wijkt de uitgestoken tong af naar de aangedane kant, met atrofie en fasciculaties bij een perifere laesie.</p>","image_url":"","wiki_title":"Hypoglossal nerve","match":"n. hypoglossus|nervus hypoglossus|hersenzenuw xii","option_only":true},"n. opticus":{"title":"N. opticus (II)","short":"De n. opticus (II) voert visuele informatie van de retina naar het chiasma opticum.","definition":"<p>De <strong>n. opticus</strong> bestaat uit de axonen van de retinale ganglioncellen. Strikt genomen is het een baan van het centrale zenuwstelsel: hij is omgeven door hersenvliezen en gemyeliniseerd door oligodendrocyten (daarom aangedaan bij MS). In het chiasma kruisen de vezels van de nasale netvlieshelften.</p>","image_url":"","wiki_title":"Optic nerve","match":"n. opticus|nervus opticus|oogzenuw|hersenzenuw ii","option_only":true},"cerebellum":{"title":"Cerebellum (kleine hersenen)","short":"Het cerebellum coördineert beweging, evenwicht en houding en speelt een rol bij motorisch leren.","definition":"<p>Het <strong>cerebellum</strong> ligt in de achterste schedelgroeve achter de hersenstam, verbonden via drie paar pedunculi. Het vergelijkt bedoelde met uitgevoerde bewegingen en stuurt bij. Uitval geeft ataxie, intentietremor, dysmetrie, dysdiadochokinese, nystagmus en dysartrie aan dezelfde kant als de laesie.</p>","image_url":"","wiki_title":"Cerebellum","match":"cerebellum|kleine hersenen","option_only":true},"cerebrum":{"title":"Cerebrum (grote hersenen)","short":"Het cerebrum bestaat uit de twee hersenhelften met cortex, witte stof en basale kernen.","definition":"<p>Het <strong>cerebrum</strong> ontstaat uit het telencephalon. Elke hemisfeer heeft een frontale, pariëtale, temporale en occipitale kwab en de insula. De hemisferen zijn verbonden door het corpus callosum. De cortex verzorgt o.a. waarneming, motoriek, taal, geheugen en uitvoerende functies.</p>","image_url":"","wiki_title":"Cerebrum","match":"cerebrum|grote hersenen","option_only":true},"cortex cerebri":{"title":"Cortex cerebri (hersenschors)","short":"De cortex cerebri is de buitenste laag grijze stof van de grote hersenen, sterk geplooid in gyri en sulci.","definition":"<p>De <strong>cortex cerebri</strong> is 2–4 mm dik en grotendeels opgebouwd uit zes lagen (neocortex). Er worden primaire gebieden (bijv. motorische en somatosensorische cortex), unimodale associatiegebieden en multimodale associatiegebieden onderscheiden. De indeling in Brodmann-gebieden is gebaseerd op verschillen in celopbouw.</p>","image_url":"","wiki_title":"Cerebral cortex","match":"cortex cerebri|hersenschors|cerebrale cortex","option_only":true},"hippocampus":{"title":"Hippocampus","short":"De hippocampus ligt in de mediale temporaalkwab en is essentieel voor het vastleggen van nieuwe herinneringen.","definition":"<p>De <strong>hippocampus</strong> is onderdeel van het limbisch systeem en ligt in de bodem van de onderhoorn van de laterale ventrikel. Hij is nodig om nieuwe episodische en ruimtelijke herinneringen op te slaan (consolidatie). De belangrijkste uitgang is de fornix. Hij is gevoelig voor hypoxie en wordt vroeg aangetast bij de ziekte van Alzheimer.</p>","image_url":"","wiki_title":"Hippocampus","match":"hippocampus","option_only":true},"epileptische aanval":{"title":"Epileptische aanval","short":"Een epileptische aanval is een kortdurende verandering in gedrag, bewustzijn of waarneming door een abnormale, overmatige ontlading van neuronen.","definition":"<p>Een <strong>epileptische aanval</strong> kan focaal beginnen (in één hersengebied, met of zonder bewustzijnsdaling) of gegeneraliseerd zijn (bijv. tonisch-klonisch of absence). Een aanval kan uitgelokt worden (bijv. door hypoglykemie, alcoholonthouding of koorts bij jonge kinderen) of passen bij epilepsie. Een aanval die langer dan 5 minuten duurt wordt behandeld als status epilepticus.</p>","image_url":"","wiki_title":"Epileptic seizure","match":"epileptische aanval|insult|epileptisch insult","option_only":true},"cva":{"title":"CVA (beroerte)","short":"Een CVA (beroerte) is plotselinge neurologische uitval door een herseninfarct of hersenbloeding.","definition":"<p>Een <strong>cerebrovasculair accident</strong> is in ongeveer 80% van de gevallen een herseninfarct en in de rest een hersenbloeding (intracerebraal of subarachnoïdaal). Beeldvorming (CT) is nodig om bloeding en infarct te onderscheiden, omdat de behandeling sterk verschilt. Belangrijke risicofactoren zijn hypertensie, roken, diabetes, hypercholesterolemie en boezemfibrilleren.</p>","image_url":"","wiki_title":"Stroke","match":"cva|beroerte|cerebrovasculair accident|stroke","option_only":true},"resistentie":{"title":"Antibioticaresistentie","short":"Resistentie betekent dat een micro-organisme ongevoelig is (geworden) voor een middel dat het normaal zou remmen of doden.","definition":"<p><strong>Antibioticaresistentie</strong> kan intrinsiek zijn (bijv. <em>Mycoplasma</em> zonder celwand) of verworven via mutaties of overdracht van resistentiegenen (bijv. via plasmiden). Mechanismen zijn afbraak van het middel (bètalactamasen), verandering van het doelwit (bijv. PBP2a bij MRSA), verminderde opname of actieve uitpomp (effluxpompen). Overmatig antibioticagebruik selecteert resistente stammen.</p>","image_url":"","wiki_title":"Antimicrobial resistance","match":"resistentie|antibioticaresistentie","option_only":true},"copd":{"title":"COPD","short":"COPD is een chronische longziekte met niet volledig omkeerbare luchtwegobstructie, meestal door roken.","definition":"<p>Bij <strong>COPD</strong> leiden chronische ontsteking van de kleine luchtwegen en afbraak van alveolewanden (emfyseem) tot een blijvende obstructie: FEV1/FVC &lt; 0,7 na bronchodilatatie. Klachten zijn kortademigheid bij inspanning, chronische hoest en sputum, met periodes van verergering (exacerbaties). Belangrijkste behandeling: stoppen met roken, luchtwegverwijders, beweegprogramma's en vaccinaties.</p>","image_url":"","wiki_title":"Chronic obstructive pulmonary disease","match":"copd|chronic obstructive pulmonary disease|chronisch obstructieve longziekte","option_only":true},"ecg":{"title":"ECG (elektrocardiogram)","short":"Een ECG registreert de elektrische activiteit van het hart via elektroden op de huid.","definition":"<p>Een standaard <strong>12-afleidingen-ECG</strong> laat de P-top (boezemdepolarisatie), het QRS-complex (kamerdepolarisatie) en de T-top (repolarisatie) zien. Het wordt gebruikt om ritmestoornissen, geleidingsstoornissen, ischemie en infarct, hypertrofie en elektrolytstoornissen (bijv. hyperkaliëmie) op te sporen.</p>","image_url":"","wiki_title":"Electrocardiography","match":"ecg|elektrocardiogram|ekg","option_only":true},"ritmestoornis":{"title":"Hartritmestoornis","short":"Een hartritmestoornis is een afwijkend hartritme: te snel, te langzaam of onregelmatig.","definition":"<p><strong>Hartritmestoornissen</strong> worden ingedeeld in brady-aritmieën (bijv. sinusknoopdysfunctie, AV-blok) en tachy-aritmieën, die supraventriculair (bijv. boezemfibrilleren, AVNRT) of ventriculair (ventrikeltachycardie, ventrikelfibrilleren) kunnen zijn. Klachten variëren van hartkloppingen en duizeligheid tot syncope en plotse dood. Diagnose met ECG of langdurige ritmeregistratie.</p>","image_url":"","wiki_title":"Cardiac arrhythmia","match":"ritmestoornis|hartritmestoornis|aritmie","option_only":true},"ventrikelfibrilleren":{"title":"Ventrikelfibrilleren","short":"Ventrikelfibrilleren is een chaotische elektrische activiteit van de kamers zonder effectieve pompfunctie: een circulatiestilstand.","definition":"<p>Bij <strong>ventrikelfibrilleren</strong> pompt het hart geen bloed meer; binnen seconden treedt bewusteloosheid op. Het ontstaat vaak bij acute ischemie, een oud infarctlitteken, cardiomyopathie of elektrolytstoornissen. De behandeling is direct reanimeren en zo snel mogelijk defibrilleren (AED).</p>","image_url":"","wiki_title":"Ventricular fibrillation","match":"ventrikelfibrilleren|ventrikelfibrillatie|vf","option_only":true},"bradycardie":{"title":"Bradycardie","short":"Bradycardie is een trage hartslag, bij volwassenen meestal onder 50–60 slagen per minuut.","definition":"<p><strong>Bradycardie</strong> kan fysiologisch zijn (bijv. bij getrainde sporters en tijdens de slaap) of pathologisch, door sinusknoopdysfunctie, AV-blok, medicatie (bètablokkers, digoxine, verapamil), hypothyreoïdie, hypothermie of verhoogde intracraniële druk. Klachten zijn moeheid, duizeligheid en syncope.</p>","image_url":"","wiki_title":"Bradycardia","match":"bradycardie","option_only":true},"hypotensie":{"title":"Hypotensie","short":"Hypotensie is een lage bloeddruk; klinisch relevant als ze leidt tot klachten of onvoldoende doorbloeding van organen.","definition":"<p><strong>Hypotensie</strong> kan constitutioneel en onschuldig zijn. Pathologische hypotensie ontstaat bij ondervulling (bloedverlies, dehydratie), vaatverwijding (sepsis, anafylaxie, medicatie), verminderde pompfunctie (cardiogeen) of obstructie (tamponnade, longembolie). Orthostatische hypotensie treedt op bij opstaan. Een daling van de doorbloeding geeft duizeligheid, verwardheid, oligurie en uiteindelijk shock.</p>","image_url":"","wiki_title":"Hypotension","match":"hypotensie|lage bloeddruk","option_only":true},"orthostatische hypotensie":{"title":"Orthostatische hypotensie","short":"Orthostatische hypotensie is een bloeddrukdaling bij het opstaan door onvoldoende compensatie van het autonome zenuwstelsel.","definition":"<p>Bij <strong>orthostatische hypotensie</strong> daalt de systolische bloeddruk met ≥20 mmHg (of de diastolische met ≥10 mmHg) binnen 3 minuten na overeind komen. Normaal zorgt de baroreflex voor vasoconstrictie en een hogere hartfrequentie. Oorzaken zijn o.a. ondervulling, medicatie (antihypertensiva, diuretica, antidepressiva) en autonome neuropathie. Klachten: duizeligheid, wazig zien en wegraking bij opstaan.</p>","image_url":"","wiki_title":"Orthostatic hypotension","match":"orthostatische hypotensie","option_only":true},"nierinsufficiëntie":{"title":"Nierinsufficiëntie (nierfalen)","short":"Bij nierinsufficiëntie schiet de nierfunctie tekort, met ophoping van afvalstoffen en verstoring van water-, zout- en zuurhuishouding.","definition":"<p><strong>Acuut nierfalen</strong> ontstaat binnen uren tot dagen en wordt ingedeeld in prerenaal (ondervulling), renaal (bijv. acute tubulusnecrose, glomerulonefritis) en postrenaal (obstructie). <strong>Chronische nierschade</strong> is een eGFR &lt; 60 of nierschade langer dan 3 maanden, meestal door diabetes en hypertensie. Gevolgen zijn o.a. hyperkaliëmie, metabole acidose, anemie (minder EPO), botziekte en hypertensie.</p>","image_url":"","wiki_title":"Kidney failure","match":"nierinsufficiëntie|nierfalen|nierinsufficientie|chronische nierschade","option_only":true},"dehydratie":{"title":"Dehydratie","short":"Dehydratie is een tekort aan lichaamsvocht, door te weinig inname of te veel verlies (braken, diarree, zweten, polyurie).","definition":"<p>Bij <strong>dehydratie</strong> daalt het circulerend volume, met dorst, droge slijmvliezen, verminderde huidturgor, tachycardie, orthostatische hypotensie en weinig plassen. Kinderen en ouderen zijn extra kwetsbaar. Afhankelijk van verlies van water ten opzichte van zout kan de natriumconcentratie normaal, verhoogd of verlaagd zijn. Behandeling met orale rehydratie of infuus.</p>","image_url":"","wiki_title":"Dehydration","match":"dehydratie|uitdroging|ondervulling","option_only":true},"hyperglycemie":{"title":"Hyperglykemie","short":"Hyperglykemie is een te hoge bloedglucose, zoals bij diabetes mellitus.","definition":"<p>Bij <strong>hyperglykemie</strong> komt glucose boven de nierdrempel (ongeveer 10 mmol/L) in de urine, wat osmotische diurese, dorst en polyurie geeft. Ernstige ontregeling kan leiden tot diabetische ketoacidose (vooral type 1) of een hyperosmolair hyperglykemisch syndroom (vooral type 2). Ook stress, infectie en corticosteroïden kunnen de glucose verhogen.</p>","image_url":"","wiki_title":"Hyperglycemia","match":"hyperglycemie|hyperglykemie","option_only":true},"hypoglycemie":{"title":"Hypoglykemie","short":"Hypoglykemie is een te lage bloedglucose, met klachten zoals trillen, zweten, honger en bij ernstige vormen verwardheid en bewustzijnsverlies.","definition":"<p>Een <strong>hypoglykemie</strong> (meestal &lt;4 mmol/L bij diabetes) komt vooral voor bij gebruik van insuline of sulfonylureumderivaten, bij te weinig eten, inspanning of alcohol. Eerst ontstaan adrenerge klachten (trillen, zweten, hartkloppingen, honger), daarna neuroglycopene klachten (verwardheid, gedragsverandering, insulten, coma). Behandeling: snelle suikers of glucose intraveneus, of glucagon.</p>","image_url":"","wiki_title":"Hypoglycemia","match":"hypoglycemie|hypoglykemie","option_only":true},"polydipsie":{"title":"Polydipsie","short":"Polydipsie is overmatige dorst en vochtinname.","definition":"<p><strong>Polydipsie</strong> gaat vaak samen met polyurie. Oorzaken zijn o.a. diabetes mellitus (osmotische diurese), diabetes insipidus (centraal of nefrogeen), hypercalciëmie, diuretica en primaire (psychogene) polydipsie. Een dorstproef kan helpen deze oorzaken te onderscheiden.</p>","image_url":"","wiki_title":"Polydipsia","match":"polydipsie","option_only":true},"hypothyreoïdie":{"title":"Hypothyreoïdie","short":"Hypothyreoïdie is een te trage schildklierwerking, met vermoeidheid, kouwelijkheid, gewichtstoename en obstipatie.","definition":"<p><strong>Hypothyreoïdie</strong> wordt in Nederland meestal veroorzaakt door de auto-immuunziekte van Hashimoto, daarnaast na thyreoïdectomie of radioactief jodium, door medicatie (amiodaron, lithium) of zelden door hypofyse-uitval. Klachten: traagheid, kouwelijkheid, droge huid, gewichtstoename, obstipatie, bradycardie en depressieve klachten. Bij primaire hypothyreoïdie is het TSH verhoogd en het vrij T4 laag; behandeling met levothyroxine.</p>","image_url":"","wiki_title":"Hypothyroidism","match":"hypothyreoïdie|hypothyreoidie|trage schildklier","option_only":true},"hyperthyreoïdie":{"title":"Hyperthyreoïdie","short":"Hyperthyreoïdie is een te snelle schildklierwerking, met hartkloppingen, gewichtsverlies, warmte-intolerantie en onrust.","definition":"<p><strong>Hyperthyreoïdie</strong> wordt o.a. veroorzaakt door de ziekte van Graves, een toxisch multinodulair struma, een toxisch adenoom of een (tijdelijke) thyreoïditis. Klachten: hartkloppingen of boezemfibrilleren, gewichtsverlies ondanks goede eetlust, zweten, tremor, onrust, slecht slapen en diarree. Diagnose: laag TSH met verhoogd vrij T4.</p>","image_url":"","wiki_title":"Hyperthyroidism","match":"hyperthyreoïdie|hyperthyreoidie|hyperthyreoïdie|overactieve schildklier","option_only":true},"myxoedeem":{"title":"Myxoedeem","short":"Myxoedeem is deegachtige zwelling van de huid door stapeling van glycosaminoglycanen; het begrip wordt ook gebruikt voor ernstige hypothyreoïdie.","definition":"<p>Bij ernstige <strong>hypothyreoïdie</strong> stapelen glycosaminoglycanen zich op in de huid, waardoor een niet-putjesvormend, deegachtig oedeem ontstaat, vooral rond de ogen en aan handen en voeten. Een myxoedeemcoma is een levensbedreigende ontsporing met hypothermie en verlaagd bewustzijn. Pretibiaal myxoedeem is daarentegen een specifiek kenmerk van de ziekte van Graves.</p>","image_url":"","wiki_title":"Myxedema","match":"myxoedeem|myxoedema","option_only":true},"schildklier":{"title":"Schildklier (glandula thyroidea)","short":"De schildklier is een vlindervormige klier in de hals die de schildklierhormonen T4 en T3 en calcitonine maakt.","definition":"<p>De <strong>schildklier</strong> ligt vóór de trachea, onder het strottenhoofd. Folliculaire cellen nemen jodium op en maken thyroglobuline, waarmee T4 en T3 worden gevormd; deze regelen het basaal metabolisme. De afgifte wordt gestuurd door TSH uit de hypofyse. Parafolliculaire C-cellen maken calcitonine. Embryonaal daalt de schildklier af vanaf de tongbasis (ductus thyroglossus).</p>","image_url":"","wiki_title":"Thyroid","match":"schildklier|glandula thyroidea|thyroid","option_only":true},"hypofyse":{"title":"Hypofyse","short":"De hypofyse is een kleine klier onder de hersenen die via hormonen veel andere klieren aanstuurt.","definition":"<p>De <strong>hypofyse</strong> ligt in de sella turcica en is via de hypofysesteel met de hypothalamus verbonden. De <em>voorkwab</em> (adenohypofyse) maakt GH, prolactine, TSH, ACTH, LH en FSH onder invloed van releasing-hormonen. De <em>achterkwab</em> (neurohypofyse) geeft ADH en oxytocine af, die in de hypothalamus worden gemaakt.</p>","image_url":"","wiki_title":"Pituitary gland","match":"hypofyse|glandula pituitaria|hersenaanhangsel","option_only":true},"hypofyse voorkwab":{"title":"Hypofysevoorkwab (adenohypofyse)","short":"De hypofysevoorkwab maakt groeihormoon, prolactine, TSH, ACTH, LH en FSH.","definition":"<p>De <strong>adenohypofyse</strong> ontstaat embryonaal uit het zakje van Rathke (een uitstulping van het dak van de mondholte). De hormoonafgifte wordt gestuurd door releasing- en inhibiting-hormonen uit de hypothalamus, die via het portale vaatstelsel van de hypofysesteel aankomen. Dopamine remt de prolactineafgifte.</p>","image_url":"","wiki_title":"Anterior pituitary","match":"hypofyse voorkwab|hypofysevoorkwab|adenohypofyse","option_only":true},"bijniermerg":{"title":"Bijniermerg","short":"Het bijniermerg maakt adrenaline en noradrenaline; het functioneert als een omgebouwd sympathisch ganglion.","definition":"<p>Het <strong>bijniermerg</strong> ontstaat uit de neurale lijst. De chromaffiene cellen worden direct geïnnerveerd door preganglionaire sympathische vezels (via acetylcholine op nicotinerge receptoren) en geven bij stress catecholaminen af in het bloed, vooral adrenaline. Een tumor van deze cellen heet een feochromocytoom.</p>","image_url":"","wiki_title":"Adrenal medulla","match":"bijniermerg|medulla glandulae suprarenalis","option_only":true},"zona fasciculata":{"title":"Zona fasciculata","short":"De zona fasciculata is de middelste en breedste laag van de bijnierschors en maakt vooral cortisol.","definition":"<p>De bijnierschors bestaat van buiten naar binnen uit zona glomerulosa (aldosteron), <strong>zona fasciculata</strong> (glucocorticoïden) en zona reticularis (androgenen). De cellen van de fasciculata liggen in lange rijen, zijn rijk aan lipidedruppels en worden vooral door ACTH gestimuleerd.</p>","image_url":"","wiki_title":"Zona fasciculata","match":"zona fasciculata","option_only":true},"zona reticularis":{"title":"Zona reticularis","short":"De zona reticularis is de binnenste laag van de bijnierschors en maakt vooral bijnierandrogenen zoals DHEA.","definition":"<p>In de <strong>zona reticularis</strong> liggen de cellen in een netwerk van strengen. Ze maken onder invloed van ACTH vooral DHEA en DHEA-sulfaat, die perifeer kunnen worden omgezet in testosteron en oestrogenen. Bij vrouwen dragen ze bij aan de oksel- en schaambeharing; overmaat (bijv. bij congenitale bijnierhyperplasie) geeft virilisatie.</p>","image_url":"","wiki_title":"Zona reticularis","match":"zona reticularis","option_only":true},"prohormonen":{"title":"Prohormonen","short":"Prohormonen zijn inactieve voorlopers van hormonen die door splitsing of omzetting actief worden.","definition":"<p>Veel peptidehormonen worden als groter <strong>prohormoon</strong> gemaakt en in secretoire blaasjes door proteasen geknipt, bijvoorbeeld proinsuline → insuline + C-peptide en POMC → ACTH en MSH. Ook sommige niet-peptidehormonen worden als voorloper afgegeven, zoals T4 (dat perifeer wordt omgezet in het actievere T3).</p>","image_url":"","wiki_title":"Prohormone","match":"prohormonen|prohormoon","option_only":true},"groeihormoonreceptorantagonist":{"title":"Groeihormoonreceptorantagonist (pegvisomant)","short":"Een groeihormoonreceptorantagonist blokkeert de werking van groeihormoon op weefsels; gebruikt bij acromegalie.","definition":"<p><strong>Pegvisomant</strong> is een gemodificeerd groeihormoonmolecuul dat aan de groeihormoonreceptor bindt maar die niet activeert. Daardoor daalt de productie van IGF-1, die de klachten van acromegalie veroorzaakt. Het wordt gebruikt als operatie en somatostatine-analogen onvoldoende effect hebben; het verkleint de tumor zelf niet.</p>","image_url":"","wiki_title":"Pegvisomant","match":"groeihormoonreceptorantagonist|pegvisomant","option_only":true},"maturity onset diabetes of the young (mody)":{"title":"MODY","short":"MODY is een erfelijke, autosomaal dominante vorm van diabetes door een mutatie in één gen, met een begin op jonge leeftijd.","definition":"<p>Bij <strong>MODY</strong> is er een monogene stoornis in de bètacelfunctie (bijv. in GCK, HNF1A of HNF4A). Kenmerkend zijn een begin vóór ongeveer 25 jaar, diabetes in meerdere opeenvolgende generaties, geen auto-antistoffen en meestal geen overgewicht. Het type bepaalt de behandeling: sommige vormen reageren goed op sulfonylureumderivaten, de GCK-vorm heeft vaak geen behandeling nodig.</p>","image_url":"","wiki_title":"Maturity onset diabetes of the young","match":"maturity onset diabetes of the young (mody)|mody|maturity onset diabetes of the young","option_only":true},"overgewicht":{"title":"Overgewicht","short":"Overgewicht is een te hoog lichaamsgewicht ten opzichte van de lengte, gedefinieerd als een BMI tussen 25 en 30 kg/m².","definition":"<p>Bij <strong>overgewicht</strong> (BMI 25–30) en vooral bij obesitas (BMI ≥30) neemt het risico op diabetes type 2, hart- en vaatziekten, artrose en sommige kankers toe. De verdeling van het vet is belangrijk: buikvet (gemeten met de middelomtrek) is metabool ongunstiger dan vet op heupen en bovenbenen.</p>","image_url":"","wiki_title":"Overweight","match":"overgewicht","option_only":true},"rubor":{"title":"Rubor (roodheid)","short":"Rubor (roodheid) is een van de klassieke ontstekingsverschijnselen, door verwijding van de bloedvaten.","definition":"<p>De klassieke tekenen van ontsteking zijn <strong>rubor</strong> (roodheid), calor (warmte), tumor (zwelling), dolor (pijn) en functio laesa (functieverlies). Roodheid en warmte ontstaan door arterioladilatatie onder invloed van mediatoren als histamine, prostaglandinen en NO, waardoor meer bloed door het ontstoken gebied stroomt.</p>","image_url":"","wiki_title":"Inflammation","match":"rubor|roodheid","option_only":true},"osteoporose":{"title":"Osteoporose","short":"Osteoporose is een verlaagde botmassa met verzwakte botstructuur, waardoor botten sneller breken.","definition":"<p>Bij <strong>osteoporose</strong> is de afbraak van bot groter dan de opbouw. Risicofactoren: hoge leeftijd, postmenopauzaal oestrogeentekort, corticosteroïden, laag lichaamsgewicht, roken, alcohol en weinig beweging. Typische fracturen zijn wervelinzakkingen, heupfracturen en distale radiusfracturen. Diagnose met een DEXA-scan (T-score ≤ −2,5); behandeling o.a. met bisfosfonaten, calcium en vitamine D.</p>","image_url":"","wiki_title":"Osteoporosis","match":"osteoporose|botontkalking","option_only":true},"diagnose-recept model":{"title":"Diagnose-receptmodel","short":"Het diagnose-receptmodel is een arts-gecentreerde manier van consultvoeren waarin de arts diagnose en behandeling bepaalt.","definition":"<p>In het <strong>diagnose-receptmodel</strong> stelt de arts vragen, onderzoekt, stelt een diagnose en schrijft een behandeling voor; de patiënt heeft een vooral passieve rol. Het staat tegenover patiëntgerichte modellen zoals gedeelde besluitvorming, waarin de waarden en voorkeuren van de patiënt meewegen.</p>","image_url":"","wiki_title":"","match":"diagnose-recept model|diagnose-receptmodel|paternalistisch model","option_only":true},"monoamine oxydase":{"title":"Monoamineoxidase (MAO)","short":"Monoamineoxidase is een enzym in de buitenmembraan van mitochondriën dat monoamines zoals serotonine, noradrenaline en dopamine afbreekt.","definition":"<p>Er zijn twee vormen: <strong>MAO-A</strong> (vooral serotonine en noradrenaline, ook tyramine in de darm) en <strong>MAO-B</strong> (vooral dopamine). MAO-remmers worden gebruikt bij depressie (MAO-A) en de ziekte van Parkinson (MAO-B, bijv. selegiline, rasagiline). Bij niet-selectieve remmers kan tyraminerijk voedsel (oude kaas) een hypertensieve crisis geven.</p>","image_url":"","wiki_title":"Monoamine oxidase","match":"monoamine oxydase|monoamineoxidase|mao|monoamine oxidase","option_only":true},"aldehyde dehydrogenase":{"title":"Aldehydedehydrogenase","short":"Aldehydedehydrogenase zet het giftige acetaldehyde uit de alcoholafbraak om in acetaat.","definition":"<p>Bij de afbraak van ethanol zet alcoholdehydrogenase eerst ethanol om in acetaldehyde; <strong>aldehydedehydrogenase</strong> zet dat daarna om in acetaat. Een erfelijk minder actieve variant (ALDH2, veel bij mensen van Oost-Aziatische afkomst) geeft opvliegers en misselijkheid na alcohol. Disulfiram remt dit enzym bewust om alcoholgebruik te ontmoedigen.</p>","image_url":"","wiki_title":"Aldehyde dehydrogenase","match":"aldehyde dehydrogenase|aldehydedehydrogenase|aldh","option_only":true},"tyrosine":{"title":"Tyrosine","short":"Tyrosine is een aminozuur dat de bouwsteen vormt voor catecholaminen, schildklierhormonen en melanine.","definition":"<p><strong>Tyrosine</strong> wordt gemaakt uit fenylalanine (door fenylalaninehydroxylase; bij fenylketonurie werkt dit enzym niet). Uit tyrosine ontstaan via tyrosinehydroxylase L-DOPA, dopamine, noradrenaline en adrenaline; daarnaast schildklierhormoon (T3/T4) en het pigment melanine.</p>","image_url":"","wiki_title":"Tyrosine","match":"tyrosine","option_only":true},"tyrosine hydroxylase":{"title":"Tyrosinehydroxylase","short":"Tyrosinehydroxylase zet tyrosine om in L-DOPA; het is de snelheidsbepalende stap van de catecholaminesynthese.","definition":"<p><strong>Tyrosinehydroxylase</strong> heeft tetrahydrobiopterine als cofactor. Het enzym wordt geremd door de eindproducten (terugkoppeling) en geactiveerd door fosforylering bij zenuwactiviteit. De route is tyrosine → L-DOPA → dopamine → noradrenaline → adrenaline.</p>","image_url":"","wiki_title":"Tyrosine hydroxylase","match":"tyrosine hydroxylase|tyrosinehydroxylase","option_only":true},"dopamine β-hydroxylase":{"title":"Dopamine-β-hydroxylase","short":"Dopamine-β-hydroxylase zet in de synaptische blaasjes dopamine om in noradrenaline.","definition":"<p><strong>Dopamine-β-hydroxylase</strong> zit in de blaasjes van noradrenerge neuronen en chromaffiene cellen van het bijniermerg en heeft vitamine C en koper nodig. Het katalyseert de stap dopamine → noradrenaline. Een erfelijk tekort geeft ernstige orthostatische hypotensie door het ontbreken van noradrenaline.</p>","image_url":"","wiki_title":"Dopamine beta-hydroxylase","match":"dopamine β-hydroxylase|dopamine-β-hydroxylase|dopamine beta-hydroxylase","option_only":true},"adenosine kinase":{"title":"Adenosinekinase","short":"Adenosinekinase fosforyleert adenosine tot AMP en regelt zo de hoeveelheid adenosine in en rond cellen.","definition":"<p><strong>Adenosinekinase</strong> is het belangrijkste enzym dat adenosine opruimt door het om te zetten in AMP (met ATP als fosfaatdonor). Adenosine zelf werkt als signaalstof: het vertraagt de AV-geleiding, verwijdt coronaire vaten en heeft een remmend effect in het brein.</p>","image_url":"","wiki_title":"Adenosine kinase","match":"adenosine kinase|adenosinekinase","option_only":true},"adenoom":{"title":"Adenoom","short":"Een adenoom is een goedaardige tumor van klierepitheel, bijvoorbeeld een darmpoliep of een hypofyseadenoom.","definition":"<p>Een <strong>adenoom</strong> groeit expansief en zaait niet uit, maar kan (zoals in de darm) via opeenstapeling van mutaties overgaan in een adenocarcinoom. Adenomen van endocriene klieren (bijv. hypofyse, bijnier, bijschildklier) kunnen hormonen produceren en daardoor klachten geven.</p>","image_url":"","wiki_title":"Adenoma","match":"adenoom|adenomen","option_only":true},"tolerantie":{"title":"Tolerantie","short":"Tolerantie is een afgenomen reactie op een middel bij herhaald gebruik, waardoor een hogere dosis nodig is voor hetzelfde effect.","definition":"<p><strong>Tolerantie</strong> kan farmacokinetisch zijn (snellere afbraak, bijv. enzyminductie) of farmacodynamisch (aanpassing van receptoren, zoals bij opioïden, benzodiazepinen en alcohol). In de immunologie betekent tolerantie het uitblijven van een afweerreactie tegen een antigeen, zoals tegen lichaamseigen weefsel.</p>","image_url":"","wiki_title":"Drug tolerance","match":"tolerantie|gewenning","option_only":true},"positieve feedback":{"title":"Positieve terugkoppeling","short":"Bij positieve terugkoppeling versterkt de respons de oorspronkelijke prikkel, waardoor een proces zichzelf versnelt tot een eindpunt.","definition":"<p><strong>Positieve feedback</strong> is relatief zeldzaam in de fysiologie, omdat het de homeostase niet bewaart. Voorbeelden zijn de LH-piek vóór de ovulatie (door stijgend oestrogeen), de weeën tijdens de bevalling (oxytocine, reflex van Ferguson), de stollingscascade en de opening van natriumkanalen tijdens de actiepotentiaal.</p>","image_url":"","wiki_title":"Positive feedback","match":"positieve feedback|positieve terugkoppeling","option_only":true},"fysiologische antagonist":{"title":"Fysiologische antagonist","short":"Een fysiologische antagonist gaat het effect van een andere stof tegen via een ander receptor- of werkingsmechanisme.","definition":"<p>Een <strong>fysiologische antagonist</strong> bindt niet aan dezelfde receptor, maar veroorzaakt via een andere route een tegengesteld effect. Voorbeeld: adrenaline (β2-receptor) gaat de door histamine (H1-receptor) veroorzaakte bronchoconstrictie en vaatverwijding tegen bij anafylaxie. Een farmacologische antagonist bindt juist aan dezelfde receptor.</p>","image_url":"","wiki_title":"Receptor antagonist","match":"fysiologische antagonist|functionele antagonist","option_only":true},"irreversibele antagonist":{"title":"Irreversibele antagonist","short":"Een irreversibele antagonist bindt (vrijwel) blijvend aan de receptor, waardoor het maximale effect van de agonist afneemt.","definition":"<p>Een <strong>irreversibele antagonist</strong> bindt covalent of zeer sterk aan de receptor. Een hogere dosis agonist kan de blokkade daarom niet opheffen: de dosis-responscurve wordt platter (lager maximaal effect). Het effect duurt tot er nieuwe receptoren zijn aangemaakt. Een voorbeeld is fenoxybenzamine bij alfa-receptoren.</p>","image_url":"","wiki_title":"Receptor antagonist","match":"irreversibele antagonist|niet-competitieve antagonist","option_only":true},"de ziekte van graves":{"title":"Ziekte van Graves","short":"De ziekte van Graves is een auto-immuunziekte waarbij antistoffen de TSH-receptor stimuleren, met hyperthyreoïdie als gevolg.","definition":"<p>Bij de <strong>ziekte van Graves</strong> maakt het lichaam antistoffen tegen de TSH-receptor (TSI/TRAb). De schildklier wordt diffuus vergroot en overactief, met een verlaagd TSH en verhoogd vrij T4. Specifieke kenmerken zijn Graves-orbitopathie (exoftalmie) en pretibiaal myxoedeem; roken verergert de oogziekte. Behandeling met thyreostatica, radioactief jodium of operatie.</p>","image_url":"","wiki_title":"Graves' disease","match":"de ziekte van graves|ziekte van graves|morbus basedow|graves","option_only":true},"tachycardie":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie|sinustachycardie","option_only":true},"atherosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"atherosclerose|aderverkalking|arteriosclerose","option_only":true},"vasodilatatie":{"title":"Vasodilatatie","short":"Vasodilatatie is verwijding van bloedvaten door ontspanning van de gladde spier in de vaatwand.","definition":"<p><strong>Vasodilatatie</strong> verlaagt de vaatweerstand en verhoogt de doorbloeding. Mediatoren zijn o.a. NO, prostacycline, histamine, bradykinine, adenosine, CO₂ en melkzuur (lokale autoregulatie). Het speelt een rol bij ontsteking (roodheid en warmte), warmteafgifte en inspanning, en is het werkingsmechanisme van veel antihypertensiva.</p>","image_url":"","wiki_title":"Vasodilation","match":"vasodilatatie|vaatverwijding","option_only":true},"hyperbilirubinemie":{"title":"Hyperbilirubinemie","short":"Hyperbilirubinemie is een verhoogd bilirubine in het bloed, zichtbaar als icterus.","definition":"<p>Een <strong>ongeconjugeerde</strong> hyperbilirubinemie ontstaat bij versterkte afbraak van rode bloedcellen (hemolyse), verminderde conjugatie (syndroom van Gilbert, neonatale icterus) of verminderde opname. Een <strong>geconjugeerde</strong> hyperbilirubinemie past bij leverziekte of galwegobstructie, met donkere urine en ontkleurde ontlasting.</p>","image_url":"","wiki_title":"Hyperbilirubinemia","match":"hyperbilirubinemie|hyperbilirubinaemie","option_only":true},"echo":{"title":"Echografie","short":"Echografie maakt met hoogfrequente geluidsgolven beelden van weke delen en organen, zonder straling.","definition":"<p>Bij <strong>echografie</strong> zendt een transducer geluidsgolven uit en vangt de echo's op. Vocht is zwart, weefsel grijs; bot en lucht houden het geluid tegen. Het is goedkoop, snel en direct beschikbaar, en geschikt voor o.a. galblaas, nieren, schildklier, zwangerschap, hart (echocardiografie), vaten (duplex) en gewrichten. De kwaliteit hangt af van de onderzoeker en de patiënt.</p>","image_url":"","wiki_title":"Medical ultrasound","match":"echo|echografie|echoscopie|ultrageluid","option_only":true},"shared decision making model":{"title":"Gedeelde besluitvorming (shared decision making)","short":"Bij gedeelde besluitvorming kiezen arts en patiënt samen een behandeling, op basis van medische informatie en de waarden van de patiënt.","definition":"<p>Bij <strong>shared decision making</strong> doorlopen arts en patiënt stappen: bespreken dat er een keuze is, de opties met voor- en nadelen uitleggen, de voorkeuren en waarden van de patiënt verkennen en samen tot een besluit komen. Het staat tussen het paternalistische model (arts beslist) en het informatieve model (patiënt beslist alleen). Keuzehulpen kunnen het ondersteunen.</p>","image_url":"","wiki_title":"Shared decision-making in medicine","match":"shared decision making model|shared decision making|gedeelde besluitvorming|overlegmodel","option_only":true},"informatief model":{"title":"Informatief model","short":"In het informatieve model geeft de arts feitelijke informatie en kiest de patiënt zelf, zonder dat de arts een advies geeft.","definition":"<p>In het <strong>informatieve model</strong> (Emanuel en Emanuel) is de arts een technisch deskundige die alle relevante informatie geeft, terwijl de patiënt volledig autonoom beslist. Andere modellen zijn het paternalistische, het interpretatieve en het deliberatieve model; gedeelde besluitvorming ligt tussen deze uitersten.</p>","image_url":"","wiki_title":"","match":"informatief model","option_only":true},"schildklier hormoon":{"title":"Schildklierhormoon (T4 en T3)","short":"Schildklierhormoon (T4 en het actievere T3) regelt het basaal metabolisme, de groei en de ontwikkeling van het zenuwstelsel.","definition":"<p>De schildklier maakt vooral <strong>T4</strong>, dat in de weefsels wordt omgezet in het actievere <strong>T3</strong>. Het hormoon werkt via kernreceptoren en verhoogt o.a. de stofwisseling, warmteproductie en gevoeligheid voor catecholaminen. In de foetale en vroege kinderjaren is het essentieel voor de hersenontwikkeling; daarom wordt congenitale hypothyreoïdie met de hielprik opgespoord.</p>","image_url":"","wiki_title":"Thyroid hormones","match":"schildklier hormoon|schildklierhormoon|thyroxine|t4|t3","option_only":true},"de ziekte van hashimoto":{"title":"Ziekte van Hashimoto","short":"De ziekte van Hashimoto is een auto-immuunontsteking van de schildklier die meestal tot hypothyreoïdie leidt.","definition":"<p>Bij <strong>Hashimoto-thyreoïditis</strong> infiltreren lymfocyten de schildklier, met antistoffen tegen thyreoperoxidase (anti-TPO). De klier kan eerst vergroot zijn en wordt later vaak kleiner, met geleidelijk een trage schildklierwerking. Het komt vaker voor bij vrouwen en samen met andere auto-immuunziekten. Er is een licht verhoogd risico op een schildkliermalt-lymfoom.</p>","image_url":"","wiki_title":"Hashimoto's thyroiditis","match":"de ziekte van hashimoto|ziekte van hashimoto|hashimoto|thyreoïditis van hashimoto","option_only":true},"het beenmerg":{"title":"Beenmerg","short":"Weefsel in de holten van botten waar alle bloedcellen worden gevormd (hematopoëse).","definition":"<p>Het <b>beenmerg</b> vult de holten van botten. In het rode beenmerg vindt de hematopoëse plaats: de vorming van rode en witte bloedcellen en bloedplaatjes uit stamcellen.</p><p>Het is tevens de plaats waar B-lymfocyten uitrijpen.</p>","image_url":"","wiki_title":"Bone marrow","match":"het beenmerg","option_only":true},"t cel":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t cel","option_only":true},"het gesprekskader aangeven":{"title":"Gesprekskader bespreken","short":"Het gesprekskader bespreken betekent aan het begin van een gesprek uitleggen wat het doel, de duur en de opbouw van het gesprek zijn.","definition":"<p>Bij het <strong>bespreken van het gesprekskader</strong> vertelt de arts aan het begin wat de aanleiding en het doel van het gesprek zijn, hoeveel tijd er is, en hoe het gesprek ongeveer verloopt (bijvoorbeeld eerst vragen stellen, dan onderzoek, dan bespreken).</p><p>Het geeft de patiënt duidelijkheid en houvast, en vormt samen met agenderen het startpunt van een gestructureerd consult.</p>","image_url":"","wiki_title":"","match":"het gesprekskader aangeven","option_only":true},"hypovolemische shock":{"title":"Hypovolemische shock","short":"Hypovolemische shock is circulatoir falen door een tekort aan circulerend volume, bijvoorbeeld door bloedverlies of uitdroging.","definition":"<p>Bij <strong>hypovolemische shock</strong> daalt de vulling van het hart en daarmee het hartminuutvolume. Het lichaam reageert met tachycardie, vasoconstrictie (koude, bleke huid, verlengde capillaire refill) en verminderde urineproductie; de bloeddruk daalt pas laat. Behandeling: de oorzaak stoppen en volume aanvullen (bloedproducten of kristalloïden).</p>","image_url":"","wiki_title":"Hypovolemic shock","match":"hypovolemische shock","option_only":true},"septische shock":{"title":"Septische shock","short":"Septische shock is sepsis met een zo sterke vaatverwijding dat ondanks vulling vasopressoren nodig zijn, met een verhoogd lactaat.","definition":"<p>Bij <strong>septische shock</strong> leiden ontstekingsmediatoren tot vaatverwijding, capillaire lekkage en verminderde zuurstofbenutting door cellen. De huid kan aanvankelijk warm zijn. Behandeling: snel antibiotica, bronbestrijding, vochttoediening en noradrenaline. De sterfte is hoog.</p>","image_url":"","wiki_title":"Septic shock","match":"septische shock","option_only":true},"obstructieve shock":{"title":"Obstructieve shock","short":"Bij obstructieve shock wordt de bloedstroom mechanisch belemmerd, bijvoorbeeld door een harttamponnade, spanningspneumothorax of massale longembolie.","definition":"<p>Bij <strong>obstructieve shock</strong> zijn de halsvenen vaak gestuwd (verhoogde centraalveneuze druk), terwijl de bloeddruk laag is. De behandeling is gericht op het opheffen van de obstructie: pericardiocentese, ontlasten van de pneumothorax of trombolyse.</p>","image_url":"","wiki_title":"Obstructive shock","match":"obstructieve shock","option_only":true},"cytotoxische t lymfocyten":{"title":"Cytotoxische T-cellen (CD8)","short":"Cytotoxische T-cellen herkennen via MHC klasse I gepresenteerde antigenen en doden geïnfecteerde of kwaadaardige cellen.","definition":"<p><strong>CD8⁺ T-cellen</strong> doden doelcellen via perforine en granzymen of via Fas-ligand, waarna apoptose volgt. Ze zijn essentieel bij de afweer tegen virussen, intracellulaire bacteriën en tumoren, en spelen een rol bij transplantaatafstoting en sommige auto-immuunziekten.</p>","image_url":"","wiki_title":"Cytotoxic T cell","match":"cytotoxische t lymfocyten|cytotoxische t-cellen|cd8+ t-cellen|cd8","option_only":true},"n. vestibulocochlearis":{"title":"N. vestibulocochlearis (VIII)","short":"De n. vestibulocochlearis (VIII) voert informatie over horen en evenwicht van het binnenoor naar de hersenstam.","definition":"<p>De <strong>n. vestibulocochlearis</strong> bestaat uit een cochleair deel (horen) en een vestibulair deel (evenwicht) en treedt bij de brughoek de hersenstam binnen, via de inwendige gehoorgang samen met de n. facialis. Een vestibulair schwannoom groeit vanuit deze zenuw.</p>","image_url":"","wiki_title":"Vestibulocochlear nerve","match":"n. vestibulocochlearis|nervus vestibulocochlearis|n. viii|hersenzenuw viii","option_only":true},"a. thyroidea superior":{"title":"A. thyroidea superior","short":"De a. thyroidea superior is de eerste tak van de a. carotis externa en voorziet de bovenpool van de schildklier.","definition":"<p>De <strong>a. thyroidea superior</strong> loopt met de externe tak van de n. laryngeus superior naar de bovenpool van de schildklier. Bij het afbinden van deze arterie tijdens een thyreoïdectomie kan die zenuw (die de m. cricothyroideus innerveert) beschadigd raken, met een minder krachtige, lagere stem.</p>","image_url":"","wiki_title":"Superior thyroid artery","match":"a. thyroidea superior|arteria thyroidea superior","option_only":true},"g-eiwit gekoppelde receptor":{"title":"G-eiwitgekoppelde receptor","short":"G-eiwitgekoppelde receptoren hebben zeven transmembraandomeinen en geven een signaal door via een G-eiwit (Gs, Gi of Gq).","definition":"<p><strong>GPCR's</strong> vormen de grootste receptorfamilie en het doelwit van veel geneesmiddelen. Gs verhoogt cAMP (bijv. β-receptoren), Gi verlaagt cAMP (bijv. α2, µ-opioïd), Gq activeert fosfolipase C met IP₃ en calcium (bijv. α1, M1/M3). Voorbeelden zijn adrenerge, muscarinerge, histamine- en dopaminereceptoren.</p>","image_url":"","wiki_title":"G protein-coupled receptor","match":"g-eiwit gekoppelde receptor|g-eiwitgekoppelde receptor|gpcr","option_only":true},"ion-kanaal gekoppelde receptor":{"title":"Ionkanaalreceptor","short":"Een ionkanaalreceptor is een receptor die zelf een ionkanaal is: bij binding van het ligand gaat het kanaal open, waardoor binnen milliseconden een effect optreedt.","definition":"<p>Voorbeelden van <strong>ionotrope receptoren</strong> zijn de nicotinerge acetylcholinereceptor, GABA-A-receptoren (chloride), glutamaatreceptoren (AMPA, NMDA) en 5-HT3-receptoren. Ze zorgen voor snelle synaptische transmissie.</p>","image_url":"","wiki_title":"Ligand-gated ion channel","match":"ion-kanaal gekoppelde receptor|ionotrope receptor|ligand-gated ionkanaal","option_only":true},"notch receptor":{"title":"Notch-receptor","short":"Notch-receptoren regelen via direct cel-celcontact beslissingen over celdifferentiatie tijdens de ontwikkeling.","definition":"<p>Bij <strong>Notch-signalering</strong> bindt een ligand op een naburige cel aan de Notch-receptor, waarna het intracellulaire deel wordt afgeknipt (o.a. door γ-secretase) en naar de kern gaat. Het speelt een rol bij laterale inhibitie, de vorming van somieten, vaatontwikkeling en sommige leukemieën.</p>","image_url":"","wiki_title":"Notch signaling pathway","match":"notch receptor|notch receptoren|notch-signalering","option_only":true},"partiele agonist":{"title":"Partiële agonist","short":"Een partiële agonist bindt aan een receptor maar activeert die maar gedeeltelijk, ook bij volledige bezetting.","definition":"<p>Een <strong>partiële agonist</strong> heeft een intrinsieke activiteit tussen 0 en 1. In aanwezigheid van een volle agonist kan hij daardoor als antagonist werken. Voorbeelden zijn buprenorfine (µ-opioïdreceptor), varenicline (nicotinereceptor) en aripiprazol (D2-receptor).</p>","image_url":"","wiki_title":"Partial agonist","match":"partiele agonist|partiële agonist","option_only":true},"polyurie":{"title":"Polyurie","short":"Polyurie is het produceren van grote hoeveelheden urine, meer dan ongeveer 3 liter per dag.","definition":"<p>Oorzaken van <strong>polyurie</strong> zijn osmotische diurese (diabetes mellitus), diabetes insipidus (centraal of nefrogeen), primaire polydipsie, diuretica, hypercalciëmie, hypokaliëmie en herstelfase van acuut nierfalen. Het moet worden onderscheiden van frequent kleine beetjes plassen (pollakisurie).</p>","image_url":"","wiki_title":"Polyuria","match":"polyurie","option_only":true},"zwangerschapsdiabetes":{"title":"Zwangerschapsdiabetes","short":"Zwangerschapsdiabetes is een verhoogde bloedglucose die voor het eerst in de zwangerschap ontstaat, door insulineresistentie onder invloed van placentahormonen.","definition":"<p>Risicofactoren voor <strong>diabetes gravidarum</strong> zijn overgewicht, eerdere zwangerschapsdiabetes, een eerder groot kind, familie met diabetes en bepaalde afkomst. Gevolgen zijn een groot kind (macrosomie), schouderdystocie en neonatale hypoglykemie. Behandeling met dieet, eventueel insuline. Na de zwangerschap is het risico op diabetes type 2 verhoogd.</p>","image_url":"","wiki_title":"Gestational diabetes","match":"zwangerschapsdiabetes|diabetes gravidarum","option_only":true},"hartfalen":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"hartfalen|decompensatio cordis|hartinsufficiëntie","option_only":true},"substance p":{"title":"Substance P","short":"Substance P is een neuropeptide dat betrokken is bij pijngeleiding en neurogene ontsteking.","definition":"<p><strong>Substance P</strong> wordt afgegeven door sensorische (C-)vezels in de achterhoorn en perifeer in het weefsel, waar het vaatverwijding en lekkage veroorzaakt. Het werkt via NK1-receptoren; NK1-antagonisten (zoals aprepitant) worden gebruikt tegen misselijkheid door chemotherapie.</p>","image_url":"","wiki_title":"Substance P","match":"substance p|substantie p","option_only":true},"testosteron":{"title":"Testosteron","short":"Testosteron is het belangrijkste mannelijke geslachtshormoon, vooral gemaakt door de cellen van Leydig in de testis.","definition":"<p>De afgifte van <strong>testosteron</strong> wordt gestuurd door LH. Het zorgt voor de mannelijke ontwikkeling (embryonaal de gangen van Wolff), puberteit, spermatogenese (samen met FSH), spiermassa, libido en botdichtheid. In weefsels wordt het door 5α-reductase omgezet in het sterkere DHT (prostaat, huid, uitwendig genitaal) of door aromatase in oestradiol.</p>","image_url":"","wiki_title":"Testosterone","match":"testosteron","option_only":true},"catecholaminen":{"title":"Catecholaminen","short":"Catecholaminen zijn dopamine, noradrenaline en adrenaline: monoamines die uit tyrosine worden gemaakt.","definition":"<p><strong>Catecholaminen</strong> werken als neurotransmitter en hormoon (bijniermerg) via adrenerge en dopaminerge receptoren. Ze worden afgebroken door MAO en COMT; afbraakproducten (metanefrines) worden gemeten bij verdenking op een feochromocytoom.</p>","image_url":"","wiki_title":"Catecholamine","match":"catecholaminen|catecholamines","option_only":true},"cathechol-o-methyl transferase":{"title":"Catechol-O-methyltransferase (COMT)","short":"COMT is een enzym dat catecholaminen afbreekt door een methylgroep toe te voegen.","definition":"<p><strong>COMT</strong> zet o.a. adrenaline en noradrenaline om in metanefrine en normetanefrine. Bij de ziekte van Parkinson worden COMT-remmers (entacapon) samen met levodopa gegeven om de afbraak van levodopa te verminderen en het effect te verlengen.</p>","image_url":"","wiki_title":"Catechol-O-methyltransferase","match":"cathechol-o-methyl transferase|catechol-o-methyltransferase|comt","option_only":true},"peptiderge hormonen":{"title":"Peptidehormonen","short":"Peptidehormonen zijn hormonen opgebouwd uit aminozuurketens; ze binden aan receptoren op het celmembraan.","definition":"<p><strong>Peptidehormonen</strong> (bijv. insuline, glucagon, ADH, PTH, groeihormoon) zijn wateroplosbaar, worden opgeslagen in blaasjes en bij een prikkel afgegeven. Ze werken via membraanreceptoren en tweede boodschappers. Steroïd- en schildklierhormonen werken daarentegen via intracellulaire receptoren op de gentranscriptie.</p>","image_url":"","wiki_title":"Peptide hormone","match":"peptiderge hormonen|peptidehormonen","option_only":true},"somatotrope cel adenoom":{"title":"Groeihormoonproducerend adenoom","short":"Een groeihormoonproducerend hypofyseadenoom veroorzaakt bij volwassenen acromegalie en bij kinderen gigantisme.","definition":"<p>Bij <strong>acromegalie</strong> groeien handen, voeten, kaak, neus en tong; er zijn hoofdpijn, zweten, carpaletunnelsyndroom, hypertensie, diabetes en slaapapneu. Het IGF-1 is verhoogd en groeihormoon wordt niet onderdrukt in een glucosetolerantietest. Behandeling: transsfenoïdale resectie, eventueel somatostatine-analogen of pegvisomant.</p>","image_url":"","wiki_title":"Acromegaly","match":"somatotrope cel adenoom|groeihormoonproducerend adenoom|acromegalie","option_only":true},"calcitriol (1,25-dihydroxy-vitamine d3)":{"title":"Calcitriol (1,25-dihydroxyvitamine D)","short":"Calcitriol is de actieve vorm van vitamine D, gevormd in de nier onder invloed van PTH.","definition":"<p><strong>Calcitriol</strong> verhoogt de opname van calcium en fosfaat in de darm en werkt samen met PTH op bot en nier. Bij nierfalen daalt de vorming, wat bijdraagt aan hypocalciëmie en secundaire hyperparathyreoïdie; dan wordt actief vitamine D gegeven. Granulomateuze ziekten (sarcoïdose) kunnen het zelf maken, met hypercalciëmie.</p>","image_url":"","wiki_title":"Calcitriol","match":"calcitriol (1,25-dihydroxy-vitamine d3)|calcitriol|1,25-dihydroxyvitamine d","option_only":true},"calcifediol (25-hydroxy- vitamine d3)":{"title":"Calcifediol (25-OH-vitamine D)","short":"Calcifediol (25-OH-vitamine D) wordt in de lever gevormd en is de vorm die in het bloed wordt gemeten om de vitamine D-status te bepalen.","definition":"<p><strong>25-OH-vitamine D</strong> heeft een lange halfwaardetijd en weerspiegelt de voorraad uit huid en voeding. De nier zet het om in het actieve calcitriol.</p>","image_url":"","wiki_title":"Calcifediol","match":"calcifediol (25-hydroxy- vitamine d3)|calcifediol|25-oh-vitamine d","option_only":true},"ergocalciferol (vitamine d2)":{"title":"Ergocalciferol (vitamine D2)","short":"Ergocalciferol (vitamine D2) is de plantaardige vorm van vitamine D, uit schimmels en gist.","definition":"<p><strong>Vitamine D2</strong> wordt net als D3 (colecalciferol, gemaakt in de huid en uit dierlijke producten) in de lever en nier geactiveerd, maar is iets minder effectief in het verhogen van de 25-OH-vitamine D-spiegel.</p>","image_url":"","wiki_title":"Ergocalciferol","match":"ergocalciferol (vitamine d2)|ergocalciferol|vitamine d2","option_only":true},"groeihormoon":{"title":"Groeihormoon (GH)","short":"Groeihormoon wordt door de hypofysevoorkwab gemaakt en stimuleert groei, vooral via IGF-1 uit de lever.","definition":"<p><strong>Groeihormoon</strong> wordt pulsatiel afgegeven, vooral in de diepe slaap, gestimuleerd door GHRH en geremd door somatostatine. Het stimuleert via IGF-1 de lengtegroei van botten en de eiwitsynthese, en werkt direct anti-insulinair (lipolyse, hogere glucose). Een tekort geeft groeiachterstand bij kinderen; een overmaat gigantisme (vóór sluiting van de groeischijven) of acromegalie.</p>","image_url":"","wiki_title":"Growth hormone","match":"groeihormoon|gh|somatotropine","option_only":true},"situationele collaps":{"title":"Situationele syncope","short":"Bij een situationele syncope ontstaat een kortdurende wegraking in een specifieke situatie, zoals plassen, hoesten of persen.","definition":"<p><strong>Situationele syncope</strong> is een vorm van reflexsyncope: een vagale reactie veroorzaakt bradycardie en vaatverwijding. Voorbeelden zijn mictiesyncope (vooral bij mannen ’s nachts), hoestsyncope en syncope bij defecatie of slikken. Er is volledig en snel herstel.</p>","image_url":"","wiki_title":"Reflex syncope","match":"situationele collaps|situationele syncope|mictiesyncope","option_only":true},"vasovagaal":{"title":"Vasovagale syncope","short":"Een vasovagale syncope is een flauwte door een reflex met vaatverwijding en vertraging van de hartslag, uitgelokt door bijv. pijn, emotie of lang staan.","definition":"<p>Bij een <strong>vasovagale syncope</strong> gaan vaak voorboden vooraf: misselijkheid, zweten, warm gevoel en zwart voor de ogen. Na het vallen herstelt iemand snel. Het is de meest voorkomende oorzaak van wegraking bij jonge mensen en is onschuldig, al kan het letsel geven.</p>","image_url":"","wiki_title":"Vasovagal response","match":"vasovagaal|vasovagale syncope|vasovagale collaps","option_only":true},"cardiac arrest":{"title":"Circulatiestilstand","short":"Bij een circulatiestilstand pompt het hart geen bloed meer rond; zonder reanimatie overlijdt de persoon binnen minuten.","definition":"<p>Een <strong>circulatiestilstand</strong> kan worden veroorzaakt door een schokbaar ritme (ventrikelfibrilleren, polsloze VT) of een niet-schokbaar ritme (asystolie, polsloze elektrische activiteit). Direct starten met borstcompressies en zo snel mogelijk defibrilleren bepalen de overlevingskans.</p>","image_url":"","wiki_title":"Cardiac arrest","match":"cardiac arrest|circulatiestilstand|hartstilstand","option_only":true},"flushing":{"title":"Flushing","short":"Flushing is plotseling, voorbijgaand rood worden van gezicht, hals en borst door vaatverwijding.","definition":"<p>Oorzaken van <strong>flushing</strong> zijn o.a. emoties, warmte, alcohol, de overgang (opvliegers), rosacea, medicatie (niacine, calciumantagonisten, nitraten) en zeldzamer het carcinoïdsyndroom, mastocytose of een feochromocytoom.</p>","image_url":"","wiki_title":"Flushing (physiology)","match":"flushing|opvliegers","option_only":true},"autoimmuun destructie van betacellen":{"title":"Diabetes mellitus type 1","short":"Bij diabetes type 1 vernietigt het immuunsysteem de insulineproducerende bètacellen, met een absoluut insulinetekort.","definition":"<p><strong>Diabetes type 1</strong> begint meestal op jonge leeftijd, vaak met dorst, veel plassen, gewichtsverlies en soms een diabetische ketoacidose. Er zijn auto-antistoffen (bijv. tegen GAD of IA-2). Behandeling is levenslang insuline.</p>","image_url":"","wiki_title":"Type 1 diabetes","match":"autoimmuun destructie van betacellen|diabetes mellitus type 1|type 1 diabetes","option_only":true},"een reflex":{"title":"Reflex","short":"Een reflex is een snelle, onwillekeurige, stereotiepe reactie op een prikkel, via een vaste zenuwbaan (reflexboog).","definition":"<p>Een <strong>reflex</strong> is een automatische reactie op een sensorische prikkel. De onderdelen van de reflexboog zijn: receptor, afferente zenuw, schakelcentrum (ruggenmerg of hersenstam), efferente zenuw en effector (spier of klier).</p><p>Voorbeelden zijn de kniepeesreflex (monosynaptisch), de terugtrekreflex en autonome reflexen zoals de baroreceptorreflex. Reflexen kunnen aangeboren zijn of, zoals bij de conditionering van Pavlov, aangeleerd (geconditioneerde reflex).</p>","image_url":"","wiki_title":"Reflex","match":"een reflex","option_only":true},"ventrikelfibrilleren (vf)":{"title":"Ventrikelfibrilleren","short":"Ventrikelfibrilleren is een chaotische elektrische activiteit van de kamers zonder effectieve pompfunctie: een circulatiestilstand.","definition":"<p>Bij <strong>ventrikelfibrilleren</strong> pompt het hart geen bloed meer; binnen seconden treedt bewusteloosheid op. Het ontstaat vaak bij acute ischemie, een oud infarctlitteken, cardiomyopathie of elektrolytstoornissen. De behandeling is direct reanimeren en zo snel mogelijk defibrilleren (AED).</p>","image_url":"","wiki_title":"Ventricular fibrillation","match":"ventrikelfibrilleren (vf)","option_only":true},"bradycardie (lage hartfrequentie)":{"title":"Bradycardie","short":"Bradycardie is een trage hartslag, bij volwassenen meestal onder 50–60 slagen per minuut.","definition":"<p><strong>Bradycardie</strong> kan fysiologisch zijn (bijv. bij getrainde sporters en tijdens de slaap) of pathologisch, door sinusknoopdysfunctie, AV-blok, medicatie (bètablokkers, digoxine, verapamil), hypothyreoïdie, hypothermie of verhoogde intracraniële druk. Klachten zijn moeheid, duizeligheid en syncope.</p>","image_url":"","wiki_title":"Bradycardia","match":"bradycardie (lage hartfrequentie)","option_only":true},"tachycardie (hoge hartfrequentie)":{"title":"Tachycardie","short":"Tachycardie is een snelle hartslag, bij volwassenen boven 100 slagen per minuut.","definition":"<p>Een <strong>sinustachycardie</strong> is een fysiologische reactie op o.a. inspanning, koorts, pijn, angst, hypovolemie, anemie, hypoxie en hyperthyreoïdie. Pathologische tachycardieën zijn o.a. boezemfibrilleren, AVNRT en ventrikeltachycardie. Het ECG maakt het onderscheid.</p>","image_url":"","wiki_title":"Tachycardia","match":"tachycardie (hoge hartfrequentie)","option_only":true},"fysiologisch antagonisme":{"title":"Fysiologische antagonist","short":"Een fysiologische antagonist gaat het effect van een andere stof tegen via een ander receptor- of werkingsmechanisme.","definition":"<p>Een <strong>fysiologische antagonist</strong> bindt niet aan dezelfde receptor, maar veroorzaakt via een andere route een tegengesteld effect. Voorbeeld: adrenaline (β2-receptor) gaat de door histamine (H1-receptor) veroorzaakte bronchoconstrictie en vaatverwijding tegen bij anafylaxie. Een farmacologische antagonist bindt juist aan dezelfde receptor.</p>","image_url":"","wiki_title":"Receptor antagonist","match":"fysiologisch antagonisme","option_only":true},"mono amino oxidase":{"title":"Monoamineoxidase (MAO)","short":"Monoamineoxidase is een enzym in de buitenmembraan van mitochondriën dat monoamines zoals serotonine, noradrenaline en dopamine afbreekt.","definition":"<p>Er zijn twee vormen: <strong>MAO-A</strong> (vooral serotonine en noradrenaline, ook tyramine in de darm) en <strong>MAO-B</strong> (vooral dopamine). MAO-remmers worden gebruikt bij depressie (MAO-A) en de ziekte van Parkinson (MAO-B, bijv. selegiline, rasagiline). Bij niet-selectieve remmers kan tyraminerijk voedsel (oude kaas) een hypertensieve crisis geven.</p>","image_url":"","wiki_title":"Monoamine oxidase","match":"mono amino oxidase","option_only":true},"cytotoxische t-cellen":{"title":"Cytotoxische T-cellen (CD8)","short":"Cytotoxische T-cellen herkennen via MHC klasse I gepresenteerde antigenen en doden geïnfecteerde of kwaadaardige cellen.","definition":"<p><strong>CD8⁺ T-cellen</strong> doden doelcellen via perforine en granzymen of via Fas-ligand, waarna apoptose volgt. Ze zijn essentieel bij de afweer tegen virussen, intracellulaire bacteriën en tumoren, en spelen een rol bij transplantaatafstoting en sommige auto-immuunziekten.</p>","image_url":"","wiki_title":"Cytotoxic T cell","match":"cytotoxische t-cellen","option_only":true},"type 2 diabetes mellitus":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"type 2 diabetes mellitus","option_only":true},"feedforward regulatie":{"title":"Feedforward-regulatie","short":"Feedforward-regulatie is een regelmechanisme dat al reageert op een verwachte verstoring, vóórdat de geregelde grootheid verandert.","definition":"<p>Bij <strong>feedforward</strong> gebruikt het lichaam informatie over een naderende verstoring om alvast bij te sturen, bijvoorbeeld een stijging van hartfrequentie en ademhaling bij het begin van inspanning. Het werkt sneller dan feedback, maar alleen goed als de verstoring voorspelbaar is; feedback corrigeert daarna de resterende afwijking.</p>","image_url":"","wiki_title":"","match":"feedforward regulatie|feed forward regulatie|feedforward","option_only":true},"a. mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"a. mesenterica superior|arteria mesenterica superior","option_only":true},"acclimatisatie":{"title":"Acclimatisatie","short":"Acclimatisatie is de omkeerbare aanpassing van het lichaam aan een aanhoudende omgevingsverandering, zoals hitte of grote hoogte.","definition":"<p>Bij <strong>hitte</strong> gaat het lichaam na enkele dagen eerder en meer zweten, met minder zoutverlies (aldosteron), en neemt het plasmavolume toe. Op <strong>hoogte</strong> neemt de ventilatie toe en later de aanmaak van rode bloedcellen (EPO).</p>","image_url":"","wiki_title":"Acclimatization","match":"acclimatisatie|acclimatiseren","option_only":true},"parathyreoïd hormoon":{"title":"Parathyreoïd hormoon (PTH)","short":"PTH is het hormoon van de bijschildklieren dat de calciumspiegel in het bloed verhoogt.","definition":"<p><strong>PTH</strong> wordt afgegeven bij een daling van het geïoniseerde calcium. Het stimuleert (via osteoblasten en RANKL) botafbraak, verhoogt de calciumterugresorptie en fosfaatuitscheiding in de nier en activeert vitamine D. Overmaat geeft hyperparathyreoïdie met hypercalciëmie.</p>","image_url":"","wiki_title":"Parathyroid hormone","match":"parathyreoïd hormoon|pth|parathormoon|bijschildklierhormoon","option_only":true},"een feedforward regulatie":{"title":"Feedforward-regulatie","short":"Feedforward-regulatie is een regelmechanisme dat al reageert op een verwachte verstoring, vóórdat de geregelde grootheid verandert.","definition":"<p>Bij <strong>feedforward</strong> gebruikt het lichaam informatie over een naderende verstoring om alvast bij te sturen, bijvoorbeeld een stijging van hartfrequentie en ademhaling bij het begin van inspanning. Het werkt sneller dan feedback, maar alleen goed als de verstoring voorspelbaar is; feedback corrigeert daarna de resterende afwijking.</p>","image_url":"","wiki_title":"","match":"een feedforward regulatie","option_only":true},"feed-forward":{"title":"Feedforward-regulatie","short":"Feedforward-regulatie is een regelmechanisme dat al reageert op een verwachte verstoring, vóórdat de geregelde grootheid verandert.","definition":"<p>Bij <strong>feedforward</strong> gebruikt het lichaam informatie over een naderende verstoring om alvast bij te sturen, bijvoorbeeld een stijging van hartfrequentie en ademhaling bij het begin van inspanning. Het werkt sneller dan feedback, maar alleen goed als de verstoring voorspelbaar is; feedback corrigeert daarna de resterende afwijking.</p>","image_url":"","wiki_title":"","match":"feed-forward","option_only":true},"arteria mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"arteria mesenterica superior","option_only":true},"bijschildklierhormoon (pth)":{"title":"Parathyreoïd hormoon (PTH)","short":"PTH is het hormoon van de bijschildklieren dat de calciumspiegel in het bloed verhoogt.","definition":"<p><strong>PTH</strong> wordt afgegeven bij een daling van het geïoniseerde calcium. Het stimuleert (via osteoblasten en RANKL) botafbraak, verhoogt de calciumterugresorptie en fosfaatuitscheiding in de nier en activeert vitamine D. Overmaat geeft hyperparathyreoïdie met hypercalciëmie.</p>","image_url":"","wiki_title":"Parathyroid hormone","match":"bijschildklierhormoon (pth)","option_only":true},"paternalistische model":{"title":"Paternalistisch model","short":"In het paternalistische model beslist de arts wat goed is voor de patiënt, met weinig inbreng van de patiënt.","definition":"<p>Het <strong>paternalistische model</strong> (Emanuel en Emanuel) staat tegenover het informatieve model (de patiënt beslist) en gedeelde besluitvorming. Het past soms in acute situaties, maar in de meeste keuzes wordt gedeelde besluitvorming nagestreefd.</p>","image_url":"","wiki_title":"","match":"paternalistische model|paternalistisch model|paternalisme","option_only":true},"arteria hepatica communis":{"title":"A. hepatica communis","short":"De a. hepatica communis is een tak van de truncus coeliacus die de lever, galblaas en delen van maag en duodenum voorziet.","definition":"<p>De <strong>a. hepatica communis</strong> geeft de a. gastroduodenalis af en loopt verder als a. hepatica propria in het lig. hepatoduodenale, samen met de v. portae en de ductus choledochus. De a. gastroduodenalis ligt achter het duodenum en kan bloeden bij een ulcus aan de achterwand.</p>","image_url":"","wiki_title":"Common hepatic artery","match":"arteria hepatica communis|a. hepatica communis","option_only":true},"arteria splenica dextra":{"title":"A. splenica (lienalis)","short":"De a. splenica is de grootste tak van de truncus coeliacus; ze loopt kronkelend langs de bovenrand van de pancreas naar de milt.","definition":"<p>De <strong>a. splenica</strong> voorziet de milt, het grootste deel van de pancreas (corpus en staart) en via de aa. gastricae breves en a. gastro-omentalis sinistra een deel van de maag. Er bestaat geen ‘a. splenica dextra’; de milt ligt links.</p>","image_url":"","wiki_title":"Splenic artery","match":"arteria splenica dextra|a. splenica|a. lienalis|miltslagader","option_only":true},"bronchodilatatie":{"title":"Bronchodilatatie","short":"Bronchodilatatie is verwijding van de luchtwegen door ontspanning van de gladde spier in de wand.","definition":"<p><strong>Bronchodilatatie</strong> ontstaat via β2-stimulatie (salbutamol, formoterol) of via blokkade van muscarinereceptoren (ipratropium, tiotropium). De reversibiliteitstest meet de verbetering van de FEV1 na een luchtwegverwijder: een duidelijke verbetering past bij astma.</p>","image_url":"","wiki_title":"Bronchodilator","match":"bronchodilatatie|luchtwegverwijding|bronchusverwijder","option_only":true},"vasoconstrictie":{"title":"Vasoconstrictie","short":"Vasoconstrictie is vernauwing van bloedvaten door samentrekking van de gladde spier in de vaatwand.","definition":"<p><strong>Vasoconstrictie</strong> wordt veroorzaakt door o.a. sympathische activatie (α1), angiotensine II, endotheline, vasopressine en kou. Het verhoogt de bloeddruk en stuurt bloed naar vitale organen, bijvoorbeeld bij bloedverlies. In de long trekken vaten juist samen bij hypoxie.</p>","image_url":"","wiki_title":"Vasoconstriction","match":"vasoconstrictie|vaatvernauwing|perifere vasoconstrictie","option_only":true},"schildklieradenoom":{"title":"Schildklieradenoom","short":"Een schildklieradenoom is een goedaardige knobbel van schildklierweefsel, al dan niet hormoonproducerend.","definition":"<p>Een <strong>folliculair adenoom</strong> is alleen na volledige verwijdering te onderscheiden van een folliculair carcinoom (invasie van kapsel of vaten). Een <strong>toxisch adenoom</strong> maakt autonoom schildklierhormoon, met hyperthyreoïdie en een ‘heet’ nodus op de scintigrafie.</p>","image_url":"","wiki_title":"Thyroid adenoma","match":"schildklieradenoom|folliculair adenoom|toxisch adenoom","option_only":true},"insuline resistentie":{"title":"Insulineresistentie","short":"Bij insulineresistentie reageren lever, spier en vetweefsel minder op insuline, waardoor meer insuline nodig is om de glucose normaal te houden.","definition":"<p><strong>Insulineresistentie</strong> hangt samen met buikvet, inactiviteit, erfelijkheid, PCOS en zwangerschap. Zolang de bètacellen extra insuline maken blijft de glucose normaal; als ze tekortschieten ontstaat diabetes type 2. Een uiting op de huid is acanthosis nigricans.</p>","image_url":"","wiki_title":"Insulin resistance","match":"insuline resistentie|insulineresistentie","option_only":true},"informatieve model":{"title":"Informatief model","short":"In het informatieve model geeft de arts feitelijke informatie en kiest de patiënt zelf, zonder dat de arts een advies geeft.","definition":"<p>In het <strong>informatieve model</strong> (Emanuel en Emanuel) is de arts een technisch deskundige die alle relevante informatie geeft, terwijl de patiënt volledig autonoom beslist. Andere modellen zijn het paternalistische, het interpretatieve en het deliberatieve model; gedeelde besluitvorming ligt tussen deze uitersten.</p>","image_url":"","wiki_title":"","match":"informatieve model","option_only":true},"autocriene regulatie":{"title":"Autocriene signalering","short":"De cel scheidt een signaalstof af waarop hij zélf reageert.","definition":"<p>Bij <b>autocriene signalering</b> geeft een cel een signaalmolecuul af dat bindt aan receptoren op diezelfde cel.</p><p>De cel stuurt dus zichzelf. Dit komt onder meer voor bij groeiregulatie en bij tumorcellen die hun eigen groei aanjagen.</p>","image_url":"","wiki_title":"Autocrine signaling","match":"autocriene regulatie","option_only":true},"osteocyt":{"title":"Osteocyt","short":"Een osteocyt is een botcel die is ingesloten in de botmatrix en via uitlopers met andere botcellen communiceert.","definition":"<p><strong>Osteocyten</strong> ontstaan uit osteoblasten die zich hebben ingemetseld. Ze liggen in lacunes en zijn verbonden via canaliculi. Ze meten mechanische belasting en sturen zo de botombouw (o.a. via sclerostine en RANKL), en maken FGF23, dat de fosfaathuishouding regelt.</p>","image_url":"","wiki_title":"Osteocyte","match":"osteocyt|osteocyten","option_only":true},"lactaat":{"title":"Lactaat","short":"Lactaat ontstaat uit pyruvaat bij anaerobe glycolyse; een verhoogd lactaat in het bloed wijst vaak op weefselhypoxie.","definition":"<p>Bij onvoldoende zuurstof zet lactaatdehydrogenase pyruvaat om in <strong>lactaat</strong> om NAD⁺ te regenereren. De lever kan lactaat weer omzetten in glucose (Cori-cyclus). Een verhoogd lactaat bij shock of sepsis is een maat voor de ernst; ook leverfalen, metformine en intoxicaties kunnen het verhogen.</p>","image_url":"","wiki_title":"Lactic acid","match":"lactaat|melkzuur","option_only":true},"echocardiografie":{"title":"Echocardiografie","short":"Echocardiografie is een echo van het hart, waarmee structuur, kleppen en pompfunctie worden beoordeeld.","definition":"<p>Met <strong>echocardiografie</strong> worden o.a. de ejectiefractie, wanddikte, klepafwijkingen, pericardvocht en aangeboren afwijkingen beoordeeld. Een transoesofageale echo geeft betere beelden van kleppen en het linkerhartoor (endocarditis, stolsels).</p>","image_url":"","wiki_title":"Echocardiography","match":"echocardiografie|echo hart|cardiale echo","option_only":true},"decompensatio cordis":{"title":"Hartfalen","short":"Bij hartfalen kan het hart onvoldoende bloed rondpompen voor de behoefte van het lichaam, met kortademigheid, vermoeidheid en vochtophoping.","definition":"<p><strong>Hartfalen</strong> wordt ingedeeld naar ejectiefractie (verminderd, licht verminderd, behouden). Oorzaken zijn o.a. ischemie, hypertensie, klepziekten en cardiomyopathieën. Klachten: inspanningsdyspneu, orthopneu, oedeem, gewichtstoename. Diagnose met NT-proBNP en echocardiografie. Behandeling bij verminderde EF: ACE-remmer/ARNI, bètablokker, MRA, SGLT2-remmer en diuretica bij overvulling.</p>","image_url":"","wiki_title":"Heart failure","match":"decompensatio cordis","option_only":true},"endocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"endocriene pancreas","option_only":true},"exocriene pancreas":{"title":"Pancreas","short":"De pancreas is zowel een exocriene klier (verteringsenzymen en bicarbonaat naar het duodenum) als een endocriene klier (insuline en glucagon uit de eilandjes van Langerhans).","definition":"<p>De <strong>pancreas</strong> ligt retroperitoneaal achter de maag, met de kop in de bocht van het duodenum.</p><p>Het <em>exocriene</em> deel (±98%) maakt verteringsenzymen (trypsine(ogeen), lipase, amylase) en bicarbonaatrijk sap, dat via de ductus pancreaticus samen met de galweg in het duodenum uitmondt. Het <em>endocriene</em> deel bestaat uit de eilandjes van Langerhans met bètacellen (insuline), alfacellen (glucagon) en deltacellen (somatostatine).</p>","image_url":"","wiki_title":"Pancreas","match":"exocriene pancreas","option_only":true},"echocardiografie (echo hart)":{"title":"Echocardiografie","short":"Echocardiografie is een echo van het hart, waarmee structuur, kleppen en pompfunctie worden beoordeeld.","definition":"<p>Met <strong>echocardiografie</strong> worden o.a. de ejectiefractie, wanddikte, klepafwijkingen, pericardvocht en aangeboren afwijkingen beoordeeld. Een transoesofageale echo geeft betere beelden van kleppen en het linkerhartoor (endocarditis, stolsels).</p>","image_url":"","wiki_title":"Echocardiography","match":"echocardiografie (echo hart)","option_only":true},"psychogene polidipsie":{"title":"Polydipsie","short":"Polydipsie is overmatige dorst en vochtinname.","definition":"<p><strong>Polydipsie</strong> gaat vaak samen met polyurie. Oorzaken zijn o.a. diabetes mellitus (osmotische diurese), diabetes insipidus (centraal of nefrogeen), hypercalciëmie, diuretica en primaire (psychogene) polydipsie. Een dorstproef kan helpen deze oorzaken te onderscheiden.</p>","image_url":"","wiki_title":"Polydipsia","match":"psychogene polidipsie","option_only":true},"processus uncinatus":{"title":"Processus uncinatus","short":"De processus uncinatus is een haakvormig uitsteeksel, o.a. van de pancreaskop achter de vasa mesenterica superiora en van het zeefbeen.","definition":"<p>Het <strong>processus uncinatus van de pancreas</strong> ligt achter de a. en v. mesenterica superior. Ook het zeefbeen en de halswervels (unco-vertebrale gewrichten) hebben een processus uncinatus.</p>","image_url":"","wiki_title":"Uncinate process of pancreas","match":"processus uncinatus","option_only":true},"eeg":{"title":"EEG (elektro-encefalogram)","short":"Een EEG registreert de elektrische activiteit van de hersenen via elektroden op de hoofdhuid.","definition":"<p>Een <strong>EEG</strong> wordt vooral gebruikt bij epilepsie (epileptiforme afwijkingen, type epilepsie), bij onverklaarde bewustzijnsstoornissen (non-convulsieve status, encefalopathie) en bij slaaponderzoek. Een normaal EEG tussen aanvallen sluit epilepsie niet uit.</p>","image_url":"","wiki_title":"Electroencephalography","match":"eeg|elektro-encefalogram","option_only":true},"riedel thyreoiditis":{"title":"Thyreoïditis van Riedel","short":"Bij thyreoïditis van Riedel wordt de schildklier vervangen door hard bindweefsel dat ingroeit in omliggende structuren.","definition":"<p>De <strong>thyreoïditis van Riedel</strong> is zeldzaam en kan lijken op een schildkliercarcinoom (harde, vaste klier) en compressie geven van trachea of slokdarm. Ze kan horen bij IgG4-gerelateerde ziekte.</p>","image_url":"","wiki_title":"Riedel's thyroiditis","match":"riedel thyreoiditis|riedel thyreoïditis","option_only":true},"thyreoiditis":{"title":"Thyreoïditis","short":"Thyreoïditis is een ontsteking van de schildklier, met vaak eerst een te snelle en daarna een te trage schildklierwerking.","definition":"<p>Bij <strong>subacute (De Quervain) thyreoïditis</strong> na een virusinfectie is de schildklier pijnlijk, met koorts en een verhoogde BSE; bij <strong>stille of postpartum thyreoïditis</strong> is er geen pijn. In de eerste fase lekt hormoon uit de klier (hyperthyreoïdie met lage opname op de scintigrafie), daarna kan een tijdelijke hypothyreoïdie volgen.</p>","image_url":"","wiki_title":"Thyroiditis","match":"thyreoiditis|thyreoïditis|(subacute) thyreoïditis|subacute thyreoïditis|ziekte van de quervain (schildklier)","option_only":true},"euthyreoidie":{"title":"Euthyreoïdie","short":"Euthyreoïdie betekent een normale schildklierfunctie, met normale waarden van TSH en vrij T4.","definition":"<p>Bij een struma of schildklierknobbel kan iemand <strong>euthyreoot</strong> zijn. Bij ernstig zieke mensen kunnen de schildklierwaarden afwijken zonder schildklierziekte (non-thyroidal illness).</p>","image_url":"","wiki_title":"","match":"euthyreoidie|euthyreoïdie|euthyreoot","option_only":true},"groeischijven":{"title":"Groeischijf (epifysairschijf)","short":"De groeischijf is een plaat van kraakbeen tussen epifyse en metafyse waar de lengtegroei van botten plaatsvindt.","definition":"<p>Na de puberteit sluiten de <strong>groeischijven</strong> onder invloed van oestrogeen (ook bij jongens, via aromatase). Fracturen door de groeischijf worden ingedeeld volgens Salter-Harris en kunnen groeistoornissen geven. De botleeftijd wordt bepaald op een handfoto.</p>","image_url":"","wiki_title":"Epiphyseal plate","match":"groeischijven|groeischijf|epifysairschijf","option_only":true},"arteria carotis interna":{"title":"A. carotis interna","short":"De a. carotis interna voorziet het grootste deel van de grote hersenen en het oog; ze geeft geen takken af in de hals.","definition":"<p>De <strong>a. carotis interna</strong> loopt door het rotsbeen en de sinus cavernosus en splitst in de a. cerebri anterior en media; de eerste tak is de a. ophthalmica. Een stenose of dissectie kan een TIA, herseninfarct of amaurosis fugax geven.</p>","image_url":"","wiki_title":"Internal carotid artery","match":"arteria carotis interna|a. carotis interna|carotis interna","option_only":true},"a. carotis externa":{"title":"A. carotis externa","short":"De a. carotis externa voorziet gezicht, hals, schedel en dura; ze heeft veel takken in de hals.","definition":"<p>Takken van de <strong>a. carotis externa</strong> zijn o.a. de a. thyroidea superior, a. lingualis, a. facialis, a. occipitalis, a. temporalis superficialis en a. maxillaris (met de a. meningea media).</p>","image_url":"","wiki_title":"External carotid artery","match":"a. carotis externa|carotis externa","option_only":true},"metacommunicatie":{"title":"Metacommunicatie","short":"Metacommunicatie is communiceren over de communicatie zelf: benoemen wat er in het gesprek gebeurt.","definition":"<p>Bij <strong>metacommunicatie</strong> stapt de arts even uit de inhoud (‘ik merk dat we langs elkaar heen praten’). Het helpt bij weerstand, irritatie of een vastgelopen gesprek. Een voorbeeld is de hier-en-nu-opmerking.</p>","image_url":"","wiki_title":"Metacommunication","match":"metacommunicatie","option_only":true},"inverse agonist":{"title":"Inverse agonist","short":"Een inverse agonist bindt aan een receptor met spontane activiteit en verlaagt die activiteit tot onder het basisniveau.","definition":"<p>Een <strong>inverse agonist</strong> heeft een negatieve intrinsieke activiteit. Een neutrale antagonist bindt wel, maar verandert de basisactiviteit niet; hij kan zowel agonisten als inverse agonisten blokkeren.</p>","image_url":"","wiki_title":"Inverse agonist","match":"inverse agonist","option_only":true},"trh":{"title":"TRH (thyreotropine-releasing hormoon)","short":"TRH is een hormoon uit de hypothalamus dat de hypofyse aanzet tot afgifte van TSH en ook prolactine.","definition":"<p><strong>TRH</strong> wordt geremd door schildklierhormoon (negatieve terugkoppeling). Bij primaire hypothyreoïdie stijgen TRH en TSH; doordat TRH ook prolactine stimuleert, kan dan galactorroe ontstaan.</p>","image_url":"","wiki_title":"Thyrotropin-releasing hormone","match":"trh|thyreotropine-releasing hormoon","option_only":true},"hypofyse achterkwab":{"title":"Hypofyseachterkwab (neurohypofyse)","short":"De hypofyseachterkwab geeft ADH en oxytocine af, die in de hypothalamus worden gemaakt.","definition":"<p>De <strong>neurohypofyse</strong> ontstaat embryonaal uit een uitstulping van het diencephalon en bestaat uit axonen van hypothalame neuronen en pituïcyten. Schade (trauma, operatie) geeft centrale diabetes insipidus.</p>","image_url":"","wiki_title":"Posterior pituitary","match":"hypofyse achterkwab|neurohypofyse|pars nervosa","option_only":true},"neuropeptide y":{"title":"Neuropeptide Y","short":"Neuropeptide Y is een neuropeptide in de hypothalamus dat de eetlust sterk stimuleert en het energieverbruik verlaagt.","definition":"<p><strong>NPY</strong> wordt geremd door leptine en insuline en gestimuleerd door ghreline. Daarnaast wordt het samen met noradrenaline in sympathische zenuwen afgegeven en werkt het vaatvernauwend.</p>","image_url":"","wiki_title":"Neuropeptide Y","match":"neuropeptide y|npy","option_only":true},"cardiogene shock":{"title":"Cardiogene shock","short":"Bij cardiogene shock pompt het hart te weinig bloed rond, meestal na een groot myocardinfarct.","definition":"<p>Bij <strong>cardiogene shock</strong> zijn er hypotensie, tekenen van slechte orgaandoorbloeding (koude huid, oligurie, verwardheid) en vaak longoedeem. Behandeling: revascularisatie, inotropica en eventueel mechanische ondersteuning.</p>","image_url":"","wiki_title":"Cardiogenic shock","match":"cardiogene shock","option_only":true},"zona glomerulosa":{"title":"Zona glomerulosa","short":"De zona glomerulosa is de buitenste laag van de bijnierschors en maakt aldosteron.","definition":"<p>De <strong>zona glomerulosa</strong> wordt vooral gestuurd door angiotensine II en kalium, en veel minder door ACTH. Daarom blijft de aldosteronproductie bij hypofyse-uitval grotendeels behouden, maar bij primaire bijnierinsufficiëntie (Addison) valt ze weg.</p>","image_url":"","wiki_title":"Zona glomerulosa","match":"zona glomerulosa","option_only":true},"bijschildklier":{"title":"Bijschildklieren","short":"De bijschildklieren zijn meestal vier kleine kliertjes achter de schildklier die PTH maken.","definition":"<p>De <strong>bijschildklieren</strong> ontstaan uit de derde (onderste) en vierde (bovenste) kieuwzakjes. Bij een schildklieroperatie kunnen ze beschadigd raken, met hypocalciëmie als gevolg. Een adenoom geeft primaire hyperparathyreoïdie.</p>","image_url":"","wiki_title":"Parathyroid gland","match":"bijschildklier|bijschildklieren|glandulae parathyroideae","option_only":true},"toxisch multinodulair struma":{"title":"Toxisch multinodulair struma","short":"Bij een toxisch multinodulair struma maken meerdere knobbels in een vergrote schildklier autonoom schildklierhormoon.","definition":"<p>Een <strong>toxisch multinodulair struma</strong> komt vooral bij ouderen voor en geeft hyperthyreoïdie, vaak met boezemfibrilleren. Jodiumtoediening (contrast, amiodaron) kan het verergeren. De scintigrafie toont een vlekkerig opnamepatroon. Behandeling met radioactief jodium, operatie of thyreostatica.</p>","image_url":"","wiki_title":"Toxic multinodular goitre","match":"toxisch multinodulair struma|multinodulair struma|struma","option_only":true},"osteoblasten":{"title":"Osteoblasten","short":"Osteoblasten zijn de botvormende cellen die osteoïd maken en de mineralisatie regelen.","definition":"<p><strong>Osteoblasten</strong> ontstaan uit mesenchymale cellen (via RUNX2) en maken collageen type I, alkalisch fosfatase en osteocalcine. Ze sturen via RANKL ook de osteoclasten aan. Ingemetselde osteoblasten worden osteocyten.</p>","image_url":"","wiki_title":"Osteoblast","match":"osteoblasten|osteoblast","option_only":true},"glycogenolyse":{"title":"Glycogenolyse","short":"Glycogenolyse is de afbraak van glycogeen tot glucose(-1-fosfaat), gestimuleerd door glucagon en adrenaline.","definition":"<p>Het sleutelenzym is <strong>glycogeenfosforylase</strong>. In de lever levert glycogenolyse glucose aan het bloed; in spier alleen brandstof voor de spier zelf. Enzymdefecten geven glycogeenstapelingsziekten (bijv. ziekte van McArdle in spier, Von Gierke in lever).</p>","image_url":"","wiki_title":"Glycogenolysis","match":"glycogenolyse|glycogeenafbraak","option_only":true},"calcitonine gene-related peptide":{"title":"CGRP","short":"CGRP is een sterk vaatverwijdend neuropeptide uit sensorische zenuwen, met een centrale rol bij migraine.","definition":"<p>Tijdens een migraineaanval komt <strong>CGRP</strong> vrij uit trigeminusvezels. Er zijn middelen tegen migraine die CGRP of zijn receptor blokkeren (antistoffen ter preventie, gepanten voor aanvallen).</p>","image_url":"","wiki_title":"Calcitonin gene-related peptide","match":"calcitonine gene-related peptide|cgrp|calcitonone gene –related peptide","option_only":true},"gonadotropin-releasing hormone":{"title":"GnRH","short":"GnRH is een hormoon uit de hypothalamus dat de afgifte van LH en FSH stimuleert, mits het pulsatiel wordt afgegeven.","definition":"<p>Continue blootstelling aan <strong>GnRH</strong>(-analogen) leidt juist tot onderdrukking van LH en FSH; dat wordt gebruikt bij prostaatkanker, endometriose en pubertas praecox. Een tekort geeft hypogonadotroop hypogonadisme (bijv. syndroom van Kallmann).</p>","image_url":"","wiki_title":"Gonadotropin-releasing hormone","match":"gonadotropin-releasing hormone|gnrh|gonadotrophin-releasing hormone","option_only":true},"pro drug":{"title":"Prodrug","short":"Een prodrug is een geneesmiddel dat in het lichaam pas wordt omgezet in de werkzame vorm.","definition":"<p>Voorbeelden van <strong>prodrugs</strong> zijn enalapril, clopidogrel (via CYP2C19), codeïne (via CYP2D6 naar morfine), valaciclovir en prednison. Genetische verschillen in de omzettende enzymen kunnen het effect sterk beïnvloeden.</p>","image_url":"","wiki_title":"Prodrug","match":"pro drug|prodrug","option_only":true},"biotransformatie":{"title":"Biotransformatie","short":"Biotransformatie is de omzetting van geneesmiddelen in het lichaam, vooral in de lever, zodat ze beter kunnen worden uitgescheiden.","definition":"<p>In <strong>fase I</strong> worden geneesmiddelen geoxideerd of gereduceerd, vaak door cytochroom P450; in <strong>fase II</strong> gekoppeld aan bijv. glucuronzuur of sulfaat. Enzyminductie (bijv. rifampicine, carbamazepine) en -remming (bijv. claritromycine, fluconazol) geven belangrijke interacties.</p>","image_url":"","wiki_title":"Drug metabolism","match":"biotransformatie|metabolisme van geneesmiddelen","option_only":true},"renale uitscheiding":{"title":"Renale uitscheiding","short":"Renale uitscheiding is de verwijdering van stoffen via de nier, door filtratie, tubulaire secretie en terugresorptie.","definition":"<p>Geneesmiddelen die vooral <strong>renaal</strong> worden geklaard (bijv. metformine, aminoglycosiden, DOAC's, lithium, LMWH) moeten bij een verminderde nierfunctie in een lagere dosis worden gegeven.</p>","image_url":"","wiki_title":"Renal clearance","match":"renale uitscheiding|renale klaring","option_only":true},"n. olfactorius":{"title":"N. olfactorius (I)","short":"De n. olfactorius (I) bestaat uit de axonen van reukcellen die door de lamina cribrosa naar de bulbus olfactorius lopen.","definition":"<p>Verlies van reuk (anosmie) ontstaat o.a. na virale infecties (zoals COVID-19), een schedeltrauma (fractuur van de lamina cribrosa), bij neuspoliepen en vroeg in de ziekte van Parkinson en Alzheimer. Bij het syndroom van Kallmann ontbreekt de reuk aangeboren.</p>","image_url":"","wiki_title":"Olfactory nerve","match":"n. olfactorius|nervus olfactorius|reukzenuw","option_only":true},"papillair schildklier carcinoom":{"title":"Papillair schildkliercarcinoom","short":"Het papillair schildkliercarcinoom is de meest voorkomende schildklierkanker, met een uitstekende prognose.","definition":"<p>Het <strong>papillair carcinoom</strong> zaait vooral uit via de lymfeklieren in de hals. Microscopisch zijn er papillen met kenmerkende kernen (‘Orphan Annie eyes’) en psammoomlichaampjes. Risicofactor: bestraling in de jeugd. Behandeling: (hemi)thyreoïdectomie, eventueel radioactief jodium.</p>","image_url":"","wiki_title":"Papillary thyroid cancer","match":"papillair schildklier carcinoom|papillair schildkliercarcinoom|schildkliercarcinoom","option_only":true},"receptor tyrosine kinases":{"title":"Receptortyrosinekinasen","short":"Receptortyrosinekinasen zijn membraanreceptoren die na binding van een groeifactor zichzelf en andere eiwitten fosforyleren.","definition":"<p>Voorbeelden zijn de <strong>insulinereceptor</strong>, EGFR, HER2 en VEGFR. Activerende mutaties of overexpressie spelen een rol bij kanker; tyrosinekinaseremmers en antistoffen (trastuzumab tegen HER2) grijpen hierop aan.</p>","image_url":"","wiki_title":"Receptor tyrosine kinase","match":"receptor tyrosine kinases|tyrosine kinase receptor|receptortyrosinekinase","option_only":true},"proteïne kinase a":{"title":"Proteïnekinase A","short":"Proteïnekinase A wordt geactiveerd door cAMP en fosforyleert eiwitten in de cel; het is een schakel in signalering via Gs-gekoppelde receptoren.","definition":"<p>Na stimulatie van een Gs-gekoppelde receptor (bijv. β-adrenerg, glucagon) maakt adenylaatcyclase <strong>cAMP</strong>, dat PKA activeert. Fosfodiësterasen breken cAMP af; hun remmers versterken het signaal.</p>","image_url":"","wiki_title":"Protein kinase A","match":"proteïne kinase a|pka|camp","option_only":true},"jodium deficiëntie":{"title":"Jodiumtekort","short":"Jodium is nodig voor de aanmaak van schildklierhormoon; een tekort geeft struma en hypothyreoïdie.","definition":"<p>Een <strong>jodiumtekort</strong> is wereldwijd de belangrijkste oorzaak van struma en van te voorkomen verstandelijke beperking (congenitale hypothyreoïdie). In Nederland wordt jodium aan bakkerszout toegevoegd.</p>","image_url":"","wiki_title":"Iodine deficiency","match":"jodium deficiëntie|jodiumtekort|een tekort aan jodium","option_only":true},"follikelepitheelcellen":{"title":"Folliculaire cellen van de schildklier","short":"De folliculaire cellen van de schildklier vormen follikels gevuld met colloïd en maken schildklierhormoon.","definition":"<p><strong>Thyreocyten</strong> nemen jodide op via de natrium-jodidesymporter, maken thyroglobuline en vormen met thyreoperoxidase T4 en T3. Ze worden gestuurd door TSH. Parafolliculaire C-cellen tussen de follikels maken calcitonine.</p>","image_url":"","wiki_title":"Thyroid follicular cell","match":"follikelepitheelcellen|folliculaire cellen|thyreocyten","option_only":true},"warmte-intolerantie":{"title":"Warmte-intolerantie","short":"Warmte-intolerantie (snel last hebben van warmte, zweten) past bij hyperthyreoïdie; koude-intolerantie bij hypothyreoïdie.","definition":"<p>Schildklierhormoon verhoogt het basaal metabolisme en de warmteproductie. Daarom geeft een overactieve schildklier <strong>warmte-intolerantie</strong> en een trage schildklier koude-intolerantie.</p>","image_url":"","wiki_title":"","match":"warmte-intolerantie|koude-intolerantie","option_only":true},"syndroom van cushing":{"title":"Syndroom van Cushing","short":"Het syndroom van Cushing is het geheel van klachten door langdurig te veel cortisol.","definition":"<p>Kenmerken van <strong>Cushing</strong>: centrale obesitas, vollemaansgezicht, buffalo hump, paarse striae, dunne huid, spierzwakte, hypertensie, diabetes, osteoporose en stemmingsklachten. De meest voorkomende oorzaak is gebruik van corticosteroïden. Endogene oorzaken: een ACTH-producerend hypofyseadenoom (ziekte van Cushing), ectopische ACTH-productie of een bijniertumor.</p>","image_url":"","wiki_title":"Cushing's syndrome","match":"syndroom van cushing|cushing|hypercortisolisme|morbus cushing|overmatig gebruik van corticosteroïden","option_only":true},"subchondrale sclerose":{"title":"Röntgenkenmerken van artrose","short":"De klassieke röntgenkenmerken van artrose zijn gewrichtsspleetversmalling, osteofyten, subchondrale sclerose en subchondrale cysten.","definition":"<p>Bij <strong>artrose</strong> is de gewrichtsspleet asymmetrisch versmald op de meest belaste plek. Bij ontstekingsziekten zoals reumatoïde artritis zijn er juist symmetrische versmalling, periarticulaire osteoporose en erosies, zonder osteofyten.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"subchondrale sclerose|subchondrale cysten|gewrichtspleet versmalling|osteofytvorming|osteofyten","option_only":true},"a. carotis interna":{"title":"A. carotis interna","short":"De a. carotis interna voorziet het grootste deel van de grote hersenen en het oog; ze geeft geen takken af in de hals.","definition":"<p>De <strong>a. carotis interna</strong> loopt door het rotsbeen en de sinus cavernosus en splitst in de a. cerebri anterior en media; de eerste tak is de a. ophthalmica. Een stenose of dissectie kan een TIA, herseninfarct of amaurosis fugax geven.</p>","image_url":"","wiki_title":"Internal carotid artery","match":"a. carotis interna","option_only":true},"carotis interna":{"title":"A. carotis interna","short":"De a. carotis interna voorziet het grootste deel van de grote hersenen en het oog; ze geeft geen takken af in de hals.","definition":"<p>De <strong>a. carotis interna</strong> loopt door het rotsbeen en de sinus cavernosus en splitst in de a. cerebri anterior en media; de eerste tak is de a. ophthalmica. Een stenose of dissectie kan een TIA, herseninfarct of amaurosis fugax geven.</p>","image_url":"","wiki_title":"Internal carotid artery","match":"carotis interna","option_only":true},"negatieve feedback":{"title":"Negatieve terugkoppeling","short":"Bij negatieve terugkoppeling remt het resultaat van een proces dat proces zelf; het belangrijkste mechanisme van homeostase.","definition":"<p>Voorbeelden van <strong>negatieve feedback</strong> zijn de regeling van lichaamstemperatuur, bloeddruk (baroreflex) en hormoonassen: cortisol remt CRH en ACTH, schildklierhormoon remt TRH en TSH. Bij positieve terugkoppeling versterkt het resultaat juist het proces.</p>","image_url":"","wiki_title":"Negative feedback","match":"negatieve feedback","option_only":true},"een negatieve feedback":{"title":"Negatieve terugkoppeling","short":"Bij negatieve terugkoppeling remt het resultaat van een proces dat proces zelf; het belangrijkste mechanisme van homeostase.","definition":"<p>Voorbeelden van <strong>negatieve feedback</strong> zijn de regeling van lichaamstemperatuur, bloeddruk (baroreflex) en hormoonassen: cortisol remt CRH en ACTH, schildklierhormoon remt TRH en TSH. Bij positieve terugkoppeling versterkt het resultaat juist het proces.</p>","image_url":"","wiki_title":"Negative feedback","match":"een negatieve feedback","option_only":true},"een positieve feedback":{"title":"Positieve terugkoppeling","short":"Bij positieve terugkoppeling versterkt de respons de oorspronkelijke prikkel, waardoor een proces zichzelf versnelt tot een eindpunt.","definition":"<p><strong>Positieve feedback</strong> is relatief zeldzaam in de fysiologie, omdat het de homeostase niet bewaart. Voorbeelden zijn de LH-piek vóór de ovulatie (door stijgend oestrogeen), de weeën tijdens de bevalling (oxytocine, reflex van Ferguson), de stollingscascade en de opening van natriumkanalen tijdens de actiepotentiaal.</p>","image_url":"","wiki_title":"Positive feedback","match":"een positieve feedback","option_only":true},"auto-immuun destructie van bètacellen":{"title":"Diabetes mellitus type 1","short":"Bij diabetes type 1 vernietigt het immuunsysteem de insulineproducerende bètacellen, met een absoluut insulinetekort.","definition":"<p><strong>Diabetes type 1</strong> begint meestal op jonge leeftijd, vaak met dorst, veel plassen, gewichtsverlies en soms een diabetische ketoacidose. Er zijn auto-antistoffen (bijv. tegen GAD of IA-2). Behandeling is levenslang insuline.</p>","image_url":"","wiki_title":"Type 1 diabetes","match":"auto-immuun destructie van bètacellen","option_only":true},"type 1 diabetes mellitus":{"title":"Diabetes mellitus type 1","short":"Bij diabetes type 1 vernietigt het immuunsysteem de insulineproducerende bètacellen, met een absoluut insulinetekort.","definition":"<p><strong>Diabetes type 1</strong> begint meestal op jonge leeftijd, vaak met dorst, veel plassen, gewichtsverlies en soms een diabetische ketoacidose. Er zijn auto-antistoffen (bijv. tegen GAD of IA-2). Behandeling is levenslang insuline.</p>","image_url":"","wiki_title":"Type 1 diabetes","match":"type 1 diabetes mellitus","option_only":true},"metformine (biguanide)":{"title":"Metformine","short":"Metformine is het eerstekeusmiddel bij diabetes mellitus type 2; het remt vooral de glucoseproductie door de lever.","definition":"<p><strong>Metformine</strong> is een biguanide dat de <em>gluconeogenese in de lever</em> remt en de insulinegevoeligheid van spier verbetert. Het stimuleert de insulineafgifte niet en geeft daarom op zichzelf geen hypoglykemie.</p><p>Het is eerste keus bij diabetes type 2 en is gewichtsneutraal. Bijwerkingen zijn vooral maag-darmklachten; zeldzaam is lactaatacidose (risico bij ernstige nierfunctiestoornis). Langdurig gebruik kan vitamine B12-tekort geven.</p>","image_url":"","wiki_title":"Metformin","match":"metformine (biguanide)","option_only":true},"dapagliflozine (sglt2 remmer)":{"title":"SGLT2-remmer","short":"SGLT2-remmers laten de nier glucose uitscheiden; ze verlagen de bloedglucose en beschermen hart en nieren.","definition":"<p><strong>SGLT2-remmers</strong> remmen de glucoseterugresorptie in de proximale tubulus. Naast glucoseverlaging (diabetes type 2) verminderen ze ziekenhuisopnames bij hartfalen en vertragen ze chronische nierschade. Bijwerkingen: genitale schimmelinfecties, volumedepletie en zeldzaam een euglykemische ketoacidose.</p>","image_url":"","wiki_title":"SGLT2 inhibitor","match":"dapagliflozine (sglt2 remmer)","option_only":true},"mesenterica superior":{"title":"A. mesenterica superior","short":"De a. mesenterica superior voorziet de dunne darm en het proximale colon van bloed.","definition":"<p>De <strong>a. mesenterica superior</strong> ontspringt ter hoogte van L1 uit de aorta, achter de pancreas, en loopt vóór het duodenum. Takken: aa. jejunales en ileales, a. ileocolica, a. colica dextra en media. Een acute afsluiting (embolie) geeft mesenteriale ischemie met hevige buikpijn bij weinig afwijkingen aan de buik.</p>","image_url":"","wiki_title":"Superior mesenteric artery","match":"mesenterica superior","option_only":true},"iliaca externa":{"title":"A. iliaca externa","short":"De a. iliaca externa loopt van de splitsing van de a. iliaca communis naar het lig. inguinale, waar ze a. femoralis gaat heten.","definition":"<p>De <strong>a. iliaca externa</strong> loopt langs de m. psoas en geeft vlak boven het lig. inguinale de a. epigastrica inferior en de a. circumflexa ilium profunda af. Bij een niertransplantatie wordt de donornier vaak op deze arterie aangesloten.</p>","image_url":"","wiki_title":"External iliac artery","match":"iliaca externa","option_only":true},"lienalis":{"title":"A. splenica (lienalis)","short":"De a. splenica is de grootste tak van de truncus coeliacus; ze loopt kronkelend langs de bovenrand van de pancreas naar de milt.","definition":"<p>De <strong>a. splenica</strong> voorziet de milt, het grootste deel van de pancreas (corpus en staart) en via de aa. gastricae breves en a. gastro-omentalis sinistra een deel van de maag. Er bestaat geen ‘a. splenica dextra’; de milt ligt links.</p>","image_url":"","wiki_title":"Splenic artery","match":"lienalis","option_only":true},"carpaaltunnelsyndroom":{"title":"Carpaletunnelsyndroom","short":"Bij het carpaletunnelsyndroom is de n. medianus bekneld in de carpale tunnel, met tintelingen in duim, wijs- en middelvinger.","definition":"<p>Het <strong>carpaletunnelsyndroom</strong> is de meest voorkomende zenuwbeknelling. Klachten: tintelingen en doofheid in het gebied van de n. medianus, vaak ’s nachts, verbeterend door schudden met de hand; later zwakte en atrofie van de duimmuis. Risicofactoren zijn zwangerschap, diabetes, hypothyreoïdie, reumatoïde artritis en repetitieve bewegingen. Behandeling met spalk, injectie of klieving van het lig. carpi transversum.</p>","image_url":"","wiki_title":"Carpal tunnel syndrome","match":"carpaaltunnelsyndroom","option_only":true},"g-eiwit gekoppelde receptoren":{"title":"G-eiwitgekoppelde receptor","short":"G-eiwitgekoppelde receptoren hebben zeven transmembraandomeinen en geven een signaal door via een G-eiwit (Gs, Gi of Gq).","definition":"<p><strong>GPCR's</strong> vormen de grootste receptorfamilie en het doelwit van veel geneesmiddelen. Gs verhoogt cAMP (bijv. β-receptoren), Gi verlaagt cAMP (bijv. α2, µ-opioïd), Gq activeert fosfolipase C met IP₃ en calcium (bijv. α1, M1/M3). Voorbeelden zijn adrenerge, muscarinerge, histamine- en dopaminereceptoren.</p>","image_url":"","wiki_title":"G protein-coupled receptor","match":"g-eiwit gekoppelde receptoren","option_only":true},"hypofyse adenoom":{"title":"Hypofyseadenoom","short":"Een hypofyseadenoom is een goedaardige tumor van de hypofysevoorkwab, al dan niet hormoonproducerend.","definition":"<p><strong>Hypofyseadenomen</strong> worden ingedeeld naar grootte (micro- &lt;1 cm, macroadenoom ≥1 cm) en naar hormoonproductie: o.a. prolactinoom, groeihormoon (acromegalie), ACTH (ziekte van Cushing) of niet-functionerend. Grote adenomen kunnen het chiasma opticum drukken (bitemporale hemianopsie) en uitval van andere hypofysehormonen geven.</p>","image_url":"","wiki_title":"Pituitary adenoma","match":"hypofyse adenoom","option_only":true},"cortisol (een glucocorticoid)":{"title":"Cortisol","short":"Cortisol is het belangrijkste glucocorticoïd uit de bijnierschors; het is een stresshormoon met effecten op stofwisseling en afweer.","definition":"<p><strong>Cortisol</strong> wordt gemaakt in de zona fasciculata onder invloed van ACTH, met een dagritme (hoog in de ochtend). Het verhoogt de bloedglucose (gluconeogenese), breekt eiwitten af, remt ontsteking en afweer en ondersteunt de bloeddruk. Overmaat geeft het syndroom van Cushing, tekort bijnierinsufficiëntie (ziekte van Addison).</p>","image_url":"","wiki_title":"Cortisol","match":"cortisol (een glucocorticoid)","option_only":true},"epinefrine":{"title":"Adrenaline (epinefrine)","short":"Adrenaline is een catecholamine uit het bijniermerg dat de ‘fight-or-flight’-reactie aanstuurt via alfa- en bèta-receptoren.","definition":"<p><strong>Adrenaline</strong> wordt door chromaffiene cellen van het bijniermerg afgegeven bij stress. Het verhoogt hartfrequentie en contractiekracht (β1), verwijdt de bronchi (β2), vernauwt vaten in huid en darm (α1) en verhoogt de bloedglucose. Als geneesmiddel is het het middel bij anafylaxie (intramusculair) en wordt het gebruikt bij reanimatie.</p>","image_url":"","wiki_title":"Adrenaline","match":"epinefrine","option_only":true},"het informatieve model":{"title":"Informatief model","short":"In het informatieve model geeft de arts feitelijke informatie en kiest de patiënt zelf, zonder dat de arts een advies geeft.","definition":"<p>In het <strong>informatieve model</strong> (Emanuel en Emanuel) is de arts een technisch deskundige die alle relevante informatie geeft, terwijl de patiënt volledig autonoom beslist. Andere modellen zijn het paternalistische, het interpretatieve en het deliberatieve model; gedeelde besluitvorming ligt tussen deze uitersten.</p>","image_url":"","wiki_title":"","match":"het informatieve model","option_only":true},"paternalisme model":{"title":"Paternalistisch model","short":"In het paternalistische model beslist de arts wat goed is voor de patiënt, met weinig inbreng van de patiënt.","definition":"<p>Het <strong>paternalistische model</strong> (Emanuel en Emanuel) staat tegenover het informatieve model (de patiënt beslist) en gedeelde besluitvorming. Het past soms in acute situaties, maar in de meeste keuzes wordt gedeelde besluitvorming nagestreefd.</p>","image_url":"","wiki_title":"","match":"paternalisme model","option_only":true},"glycogeen fosforylase":{"title":"Glycogenolyse","short":"Glycogenolyse is de afbraak van glycogeen tot glucose(-1-fosfaat), gestimuleerd door glucagon en adrenaline.","definition":"<p>Het sleutelenzym is <strong>glycogeenfosforylase</strong>. In de lever levert glycogenolyse glucose aan het bloed; in spier alleen brandstof voor de spier zelf. Enzymdefecten geven glycogeenstapelingsziekten (bijv. ziekte van McArdle in spier, Von Gierke in lever).</p>","image_url":"","wiki_title":"Glycogenolysis","match":"glycogeen fosforylase","option_only":true},"vasopressine":{"title":"Vasopressine (ADH)","short":"Vasopressine (ADH) wordt in de hypothalamus gemaakt en in de hypofyseachterkwab afgegeven; het laat de nier water terugresorberen.","definition":"<p><strong>ADH</strong> bouwt via V2-receptoren aquaporine-2 in de verzamelbuizen in, waardoor de urine geconcentreerd wordt. Via V1-receptoren werkt het vaatvernauwend. Afgifte wordt gestimuleerd door een stijgende osmolaliteit en een dalend bloedvolume. Een tekort of ongevoeligheid geeft diabetes insipidus; een overmaat SIADH.</p>","image_url":"","wiki_title":"Vasopressin","match":"vasopressine|adh|antidiuretisch hormoon","option_only":true},"transsfenoïdale resectie":{"title":"Transsfenoïdale resectie","short":"Bij een transsfenoïdale resectie wordt een hypofysetumor via de neus en de sinus sphenoidalis verwijderd.","definition":"<p>Dit is de standaardoperatie voor de meeste <strong>hypofyseadenomen</strong> (behalve prolactinomen, die meestal met dopamineagonisten worden behandeld). Complicaties: liquorlekkage, diabetes insipidus en uitval van hypofysehormonen.</p>","image_url":"","wiki_title":"Transsphenoidal surgery","match":"transsfenoïdale resectie|transsfenoidale chirurgie","option_only":true},"gliclazide (su-derivaat)":{"title":"Gliclazide","short":"Gliclazide is een sulfonylureumderivaat dat de insulineafgifte uit de bètacellen stimuleert; gebruikt bij diabetes type 2.","definition":"<p><strong>Gliclazide</strong> sluit ATP-gevoelige kaliumkanalen in de bètacel, waardoor insuline vrijkomt, ook bij een lage glucose. Het belangrijkste risico is hypoglykemie, vooral bij ouderen, bij overslaan van maaltijden en bij nierfunctiestoornissen. Het kan gewichtstoename geven.</p>","image_url":"","wiki_title":"Gliclazide","match":"gliclazide (su-derivaat)","option_only":true},"maximale effectiviteit (= efficacy)":{"title":"Efficacy (effectiviteit)","short":"Efficacy is de mate waarin een gebonden ligand de receptor kan activeren; een antagonist heeft efficacy 0.","definition":"<p><strong>Efficacy</strong> (intrinsieke activiteit) beschrijft het maximale effect dat een stof via een receptor kan bewerkstelligen, onafhankelijk van de affiniteit.</p>","image_url":"","wiki_title":"Efficacy (pharmacology)","match":"maximale effectiviteit (= efficacy)","option_only":true},"latent auto-immune diabetes in adults (lada)":{"title":"LADA","short":"Latent auto-immune diabetes in adults: langzaam verlopende auto-immune diabetes op volwassen leeftijd, aanvankelijk lijkend op type 2 maar zonder overgewicht.","definition":"<p><strong>LADA</strong> (latent auto-immune diabetes in adults) is een vorm van auto-immune diabetes die zich op volwassen leeftijd traag ontwikkelt. Patiënten hebben vaak een normaal gewicht en worden aanvankelijk voor type 2 aangezien, maar hebben eilandjes-auto-antistoffen.</p>","image_url":"","wiki_title":"Latent autoimmune diabetes in adults","match":"latent auto-immune diabetes in adults (lada)","option_only":true},"vetzuurverbranding":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuurverbranding","option_only":true},"calcitonine":{"title":"Calcitonine","short":"Hormoon uit de parafolliculaire C-cellen van de schildklier.","definition":"<p><strong>Calcitonine</strong> wordt gemaakt door de parafolliculaire C-cellen van de schildklier als reactie op een stijging van het calcium. Het remt osteoclasten. Bij de mens is de fysiologische rol beperkt: na een totale thyreoïdectomie blijft de calciumspiegel normaal. Calcitonine is een tumormarker voor het medullair schildkliercarcinoom.</p>","image_url":"","wiki_title":"Calcitonin","match":"calcitonine","option_only":true},"cholecalciferol":{"title":"Cholecalciferol (vitamine D3)","short":"Cholecalciferol is de inactieve voorloper van vitamine D die in de huid en via voeding wordt verkregen.","definition":"<p><b>Cholecalciferol</b> (vitamine D3) is een inactieve vorm van vitamine D die nog in lever (25-hydroxylatie) en nier (1-hydroxylatie) moet worden geactiveerd tot calcitriol.</p>","image_url":"","wiki_title":"Cholecalciferol","match":"cholecalciferol","option_only":true},"bijnier":{"title":"Bijnier","short":"Endocriene klier boven de nier die o.a. cortisol, aldosteron en (in het merg) catecholaminen produceert.","definition":"<p>De <b>bijnier</b> (glandula suprarenalis) grenst aan de bovenpool van de nier; links liggen milt, maag en pancreas in de nabijheid.</p>","image_url":"","wiki_title":"Adrenal gland","match":"bijnier","option_only":true},"heesheid":{"title":"Heesheid","short":"Verandering van de stemkwaliteit (hese, schorre stem) door aandoening van de stembanden of larynx.","definition":"<p>Heesheid (dysfonie) ontstaat bij afwijkingen van de stemplooien of hun innervatie. Aanhoudende heesheid (>3 weken) bij een roker is een alarmsymptoom voor larynxcarcinoom.</p>","image_url":"","wiki_title":"Hoarse voice","match":"heesheid","option_only":true},"groeihormoonreceptor antagonist":{"title":"Groeihormoonreceptorantagonist (pegvisomant)","short":"Een groeihormoonreceptorantagonist blokkeert de werking van groeihormoon op weefsels; gebruikt bij acromegalie.","definition":"<p><strong>Pegvisomant</strong> is een gemodificeerd groeihormoonmolecuul dat aan de groeihormoonreceptor bindt maar die niet activeert. Daardoor daalt de productie van IGF-1, die de klachten van acromegalie veroorzaakt. Het wordt gebruikt als operatie en somatostatine-analogen onvoldoende effect hebben; het verkleint de tumor zelf niet.</p>","image_url":"","wiki_title":"Pegvisomant","match":"groeihormoonreceptor antagonist","option_only":true},"prevertebrale ganglia":{"title":"Prevertebrale ganglia","short":"Sympatische ganglia vóór de wervelkolom (o.a. ganglion coeliacum) waar postganglionaire sympatische neuronen liggen.","definition":"<p><b>Prevertebrale ganglia</b> liggen rond de grote buikarteriën en bevatten cellichamen van postganglionaire sympatische neuronen die de buikorganen innerveren.</p>","image_url":"","wiki_title":"","match":"prevertebrale ganglia","option_only":true},"orale biologische beschikbaarheid (=bioavailability)":{"title":"Biologische beschikbaarheid","short":"De biologische beschikbaarheid (bioavailability) is de fractie van een toegediende dosis die onveranderd de systemische circulatie bereikt.","definition":"<p><strong>Biologische beschikbaarheid</strong> is per definitie 100% bij intraveneuze toediening en lager bij orale toediening door onvolledige opname en het first pass-effect.</p>","image_url":"","wiki_title":"Bioavailability","match":"orale biologische beschikbaarheid (=bioavailability)","option_only":true},"hoofdcellen":{"title":"Hoofdcellen","short":"Cellen in de maagwand die pepsinogeen produceren.","definition":"<p><b>Hoofdcellen</b> (chief cells) van de maagklieren bezitten veel ruw endoplasmatisch reticulum voor de aanmaak en secretie van pepsinogeen, het inactieve voorloperenzym van pepsine.</p>","image_url":"","wiki_title":"Gastric chief cell","match":"hoofdcellen","option_only":true},"citraat (citroenzuur)":{"title":"Citraat","short":"Eerste product van de citroenzuurcyclus, gevormd uit acetyl-CoA en oxaalacetaat.","definition":"<p><b>Citraat</b> (citroenzuur) ontstaat wanneer acetyl-CoA in de citroenzuurcyclus aan oxaalacetaat wordt gekoppeld.</p><p>Het is de eerste stap van de cyclus; de naamgever citroenzuurcyclus verwijst ernaar.</p>","image_url":"","wiki_title":"Citric acid","match":"citraat (citroenzuur)","option_only":true},"vetzuuroxidatie":{"title":"Vetzuren","short":"Vetzuren zijn koolstofketens met een carboxylgroep; ze worden via bèta-oxidatie in de mitochondriën verbrand en leveren veel ATP, maar alleen aeroob.","definition":"<p><strong>Vetzuren</strong> zijn lange koolwaterstofketens met een carboxylgroep, verzadigd of onverzadigd. Ze worden opgeslagen als triglyceriden in vetweefsel en bij behoefte door lipolyse vrijgemaakt.</p><p>In de cel worden ze met carnitine de mitochondriën in getransporteerd en via <em>bèta-oxidatie</em> afgebroken tot acetyl-CoA, dat de citroenzuurcyclus in gaat. Vetzuren leveren per gram veel meer energie dan glucose, maar alleen via zuurstofafhankelijke stofwisseling en relatief langzaam. In de lever kunnen ze ketonlichamen vormen.</p>","image_url":"","wiki_title":"Fatty acid","match":"vetzuuroxidatie","option_only":true},"nefropathie":{"title":"Nefropathie","short":"Nefropathie is nierschade; diabetische nefropathie is een gevolg van microangiopathie en een belangrijke oorzaak van nierfalen.","definition":"<p><strong>Nefropathie</strong> uit zich onder meer in albuminurie en een dalende nierfunctie.</p>","image_url":"","wiki_title":"Kidney disease","match":"nefropathie","option_only":true},"t lymfocyten":{"title":"T-cellen","short":"T-cellen zijn lymfocyten die in de thymus rijpen en antigeen herkennen dat via MHC wordt gepresenteerd; CD4-cellen helpen, CD8-cellen doden geïnfecteerde cellen.","definition":"<p><strong>T-cellen</strong> ontstaan in het beenmerg en rijpen in de <em>thymus</em>, waar positieve en negatieve selectie plaatsvindt. Hun T-celreceptor herkent alleen peptiden die door MHC-moleculen worden gepresenteerd.</p><p><em>CD4⁺ T-helpercellen</em> herkennen MHC-II en sturen de afweer met cytokines (Th1, Th2, Th17, Tfh); <em>CD8⁺ cytotoxische T-cellen</em> herkennen MHC-I en doden geïnfecteerde of tumorcellen; regulatoire T-cellen remmen de afweer. Ze vormen de cellulaire adaptieve immuniteit.</p>","image_url":"","wiki_title":"T cell","match":"t lymfocyten","option_only":true},"oxytocine":{"title":"Oxytocine","short":"Oxytocine is een hormoon uit de neurohypofyse dat de melkuitdrijving (toeschietreflex) en uteruscontracties regelt. Het onderscheidt zich van prolactine, dat de melkproductie stuurt.","definition":"<p>Hormoon dat wordt afgegeven door de achterkwab van de hypofyse. Het veroorzaakt de melkejectie tijdens borstvoeding en samentrekking van de baarmoeder tijdens de bevalling.</p>","image_url":"","wiki_title":"Oxytocin","match":"oxytocine","option_only":true},"catecholamine":{"title":"Catecholaminen","short":"Catecholaminen zijn dopamine, noradrenaline en adrenaline, die uit tyrosine worden gemaakt.","definition":"<p>De aanmaak verloopt van tyrosine via L-DOPA naar dopamine, noradrenaline en (in het bijniermerg) adrenaline. Ze worden afgebroken door MAO en COMT. Een feochromocytoom maakt een overmaat aan <strong>catecholaminen</strong>, aantoonbaar via metanefrines.</p>","image_url":"","wiki_title":"Catecholamine","match":"catecholamine|catecholaminen","option_only":true},"hyperplastische poliep":{"title":"Poliepen van het colon","short":"Darmpoliepen worden ingedeeld in adenomen (voorstadium van kanker), hyperplastische en serrated poliepen, inflammatoire en juveniele (hamartomateuze) poliepen.","definition":"<p>De meeste darmkankers ontstaan uit een <strong>adenoom</strong> (adenoom-carcinoomsequentie). Kleine hyperplastische poliepen in het rectosigmoïd zijn onschuldig; sessiele serrated laesies kunnen wel ontaarden. Juveniele poliepen zijn hamartomen; bij meerdere poliepen is een erfelijk syndroom mogelijk.</p>","image_url":"","wiki_title":"Colorectal polyp","match":"hyperplastische poliep|inflammatoire poliep|juveniele poliep|adenomateuze poliep|adenoom","option_only":true},"grensstrengganglia":{"title":"Grensstreng (truncus sympathicus)","short":"De grensstreng is een keten van sympathische ganglia aan beide kanten van de wervelkolom, waarin preganglionaire vezels overschakelen.","definition":"<p>De preganglionaire sympathische neuronen liggen in het ruggenmerg van T1 tot L2. Een onderbreking van de <strong>sympathische keten</strong> in de hals (bijv. door een Pancoast-tumor) geeft het syndroom van Horner.</p>","image_url":"","wiki_title":"Sympathetic trunk","match":"grensstrengganglia|grensstreng|truncus sympathicus|paravertebrale ganglia","option_only":true},"arterosclerose":{"title":"Atherosclerose","short":"Atherosclerose is een chronisch ontstekingsproces in de vaatwand waarbij plaques met vet, ontstekingscellen en bindweefsel ontstaan.","definition":"<p>Bij <strong>atherosclerose</strong> dringt LDL de intima binnen en wordt het geoxideerd; monocyten worden macrofagen en schuimcellen (fatty streak). Gladde spiercellen migreren en vormen een fibreuze kap over een lipidenkern. Scheuren van een plaque met trombose veroorzaakt een acuut coronair syndroom of herseninfarct. Risicofactoren: roken, hypertensie, LDL, diabetes, leeftijd en familiaire belasting.</p>","image_url":"","wiki_title":"Atherosclerosis","match":"arterosclerose","option_only":true},"glucuronidase":{"title":"Enzymen (glucuronidase, glycosyltransferase, fosfatase)","short":"Glucuronidasen splitsen glucuronzuur af, glycosyltransferasen koppelen suikers aan eiwitten of lipiden, en fosfatasen verwijderen fosfaatgroepen.","definition":"<p>In de lever worden stoffen aan glucuronzuur gekoppeld; darmbacteriën met <strong>β-glucuronidase</strong> kunnen die koppeling weer verbreken (enterohepatische kringloop). Fosfatasen werken tegengesteld aan kinasen.</p>","image_url":"","wiki_title":"","match":"glucuronidase|glycosyltransferase|fosfatase|fosfatasen","option_only":true},"het paternalistische model":{"title":"Modellen van de arts-patiëntrelatie","short":"Emanuel en Emanuel beschrijven vier modellen: paternalistisch, informatief, interpretatief en deliberatief.","definition":"<p>In het <strong>paternalistische model</strong> beslist de arts wat goed is voor de patiënt. In het <strong>deliberatieve model</strong> bespreekt de arts ook welke waarden het belangrijkst zijn en probeert hij de patiënt te overtuigen, zonder te dwingen. In het interpretatieve model helpt de arts de patiënt eigen waarden te verhelderen.</p>","image_url":"","wiki_title":"","match":"het paternalistische model|paternalistische model|het deliberatieve model|deliberatief model|interpretatief model","option_only":true},"geactiveerd protein kinase c":{"title":"Proteïnekinase C","short":"Proteïnekinase C wordt geactiveerd door diacylglycerol en calcium, na stimulatie van Gq-gekoppelde receptoren.","definition":"<p>Bij <strong>Gq-signalering</strong> splitst fosfolipase C PIP2 in IP3 en diacylglycerol (DAG); DAG activeert proteïnekinase C. Voorbeelden van Gq-receptoren zijn α1-adrenerge, M1- en M3-receptoren.</p>","image_url":"","wiki_title":"Protein kinase C","match":"geactiveerd protein kinase c|proteïnekinase c|pkc|diacylglycerol","option_only":true},"inositolkinase":{"title":"Fosfoinositide-signalering","short":"Fosfoinositiden zijn membraanlipiden die bij signalering worden gefosforyleerd (door kinasen zoals PI3-kinase) of gesplitst.","definition":"<p>Het <strong>PI3-kinase/Akt</strong>-pad wordt o.a. door de insulinereceptor geactiveerd en speelt een rol bij glucoseopname en celgroei; het is vaak ontregeld bij kanker.</p>","image_url":"","wiki_title":"","match":"inositolkinase|diacylglycerolcyclase|pi3-kinase","option_only":true},"pars distalis":{"title":"Delen van de hypofyse","short":"De hypofysevoorkwab (adenohypofyse) bestaat uit de pars distalis, pars intermedia en pars tuberalis; de achterkwab is de pars nervosa.","definition":"<p>In de <strong>pars distalis</strong> worden de meeste voorkwabhormonen gemaakt (GH, prolactine, ACTH, TSH, LH, FSH). De voorkwab ontstaat uit het zakje van Rathke (dak van de mondholte), de achterkwab uit het diencephalon.</p>","image_url":"","wiki_title":"Anterior pituitary","match":"pars distalis|pars intermedia|pars tuberalis|adenohypofyse","option_only":true},"lamina pretrachealis":{"title":"Fascies van de hals","short":"De diepe halsfascie bestaat uit de lamina superficialis, de lamina pretrachealis (rond trachea, slokdarm en schildklier) en de lamina prevertebralis, plus de vagina carotica rond de vaatzenuwstreng.","definition":"<p>De <strong>vagina carotica</strong> omhult de a. carotis communis, de v. jugularis interna en de n. vagus. De ruimtes tussen de fascies kunnen infecties naar het mediastinum laten uitbreiden (mediastinitis).</p>","image_url":"","wiki_title":"Deep cervical fascia","match":"lamina pretrachealis|vagina carotica|ingewandfascie|lamina superficialis","option_only":true},"verhoogd prolactine":{"title":"Hyperprolactinemie","short":"Hyperprolactinemie is een verhoogd prolactine in het bloed, met galactorroe, cyclusstoornissen en een verminderd libido.","definition":"<p>Oorzaken zijn een <strong>prolactinoom</strong>, antipsychotica en andere dopamineantagonisten (metoclopramide), hypothyreoïdie, zwangerschap en compressie van de hypofysesteel. Behandeling van een prolactinoom met dopamineagonisten (cabergoline).</p>","image_url":"","wiki_title":"Hyperprolactinaemia","match":"verhoogd prolactine|hyperprolactinemie|prolactinoom","option_only":true},"diabetes mellitus van de moeder":{"title":"Diabetes in de zwangerschap","short":"Diabetes bij de moeder (vooraf bestaand of zwangerschapsdiabetes) verhoogt het risico op een groot kind, schouderdystocie, aangeboren afwijkingen en neonatale hypoglykemie.","definition":"<p>Bij vooraf bestaande diabetes is een goede glucoseregulatie vóór de conceptie belangrijk om aangeboren afwijkingen te voorkomen. <strong>Zwangerschapsdiabetes</strong> wordt behandeld met dieet en zo nodig insuline of metformine.</p>","image_url":"","wiki_title":"Gestational diabetes","match":"diabetes mellitus van de moeder|zwangerschapsdiabetes|diabetes gravidarum","option_only":true}};
